// ==============================================================
// ביאור פשט מודרני לספר דברי הימים ב' (כל 36 הפרקים - 822 פסוקים מלאים)
// נבנה בשפה פשוטה, מודרנית ובהירה לקורא בן זמננו
// ==============================================================

window.Peshat2Chronicles = {
  "1_1": "ויתחזק שלמה בן דוד על מלכותו, וה' אלוהיו היה עימו ויגדלהו למעלה למאוד;",
  "1_2": "ויאמר שלמה לכל ישראל, לשרי האלפים והמאות, ולשופטים, ולכל נשיא לכל ישראל, ראשי האבות;",
  "1_3": "וילכו שלמה וכל הקהל עימו לבמה אשר בגבעון, כי שם היה אוהל מועד של האלוהים אשר עשה משה עבד ה' במדבר;",
  "1_4": "אולם ארון האלוהים העלה דוד מקריית יערים במקום אשר הכין לו דוד, כי נטה לו אוהל בירושלים;",
  "1_5": "ומזבח הנחושת אשר עשה בצלאל בן אורי בן חור הוצב שם לפני משכן ה', וידרוש בו שלמה והקהל;",
  "1_6": "ויעל שלמה שם על מזבח הנחושת לפני ה' אשר לאוהל מועד, ויעל עליו אלף עולות;",
  "1_7": "בלילה ההוא נראה אלוהים אל שלמה, ויאמר לו: 'שאל מה אתן לך!';",
  "1_8": "ויאמר שלמה לאלוהים: 'אתה עשית עם דוד אבי חסד גדול, והמלכתני תחתיו;",
  "1_9": "עתה ה' אלוהים, ייאמן ויתקיים דברך עם דוד אבי, כי אתה המלכתני על עם רב כעפר הארץ!;",
  "1_10": "עתה חכמה ומדע תן לי, ואצאה לפני העם הזה ואבואה; כי מי יוכל לשפוט את עמך הגדול הזה?!';",
  "1_11": "ויאמר אלוהים לשלמה: 'יען אשר הייתה זאת עם לבבך, ולא שאלת עושר, נכסים וכבוד, ואף לא את נפש שונאיך, וגם ימים רבים לא שאלת, אלא שאלת לך חכמה ומדע אשר תוכל לשפוט את עמי אשר המלכתיך עליו –",
  "1_12": "החכמה והמדע נתונים לך; וגם עושר, נכסים וכבוד אתן לך, אשר לא היה כן למלכים אשר היו לפניך ואחריך לא יהיה כן!';",
  "1_13": "ויבוא שלמה מן הבמה אשר בגבעון לירושלים מלפני אוהל מועד, וימלוך על ישראל;",
  "1_14": "וייאסוף שלמה רכב ופרשים; ויהי לו אלף וארבע מאות רכב ושנים עשר אלף פרשים, ויניחם בערי הרכב ועם המלך בירושלים;",
  "1_15": "וייתן המלך את הכסף ואת הזהב בירושלים כאבנים, ואת הארזים נתן כשקמים אשר בשפלה לרוב עצום;",
  "1_16": "ומוצא הסוסים אשר לשלמה היה ממצרים ומקווה (קווה שבאסיה הקטנה); סוחרי המלך לקחו קבוצות סוסים במחיר קבוע;",
  "1_17": "והעלו והוציאו מרכבה ממצרים בשש מאות שקלי כסף, וסוס במאה וחמישים; וכן לכל מלכי החיתים ומלכי ארם על ידם הוציאו;",
  "1_18": "ויאמר שלמה לבנות בית לשם ה', וארמון מלוכה למלכותו.",
  "2_1": "ויספור שלמה שבעים אלף איש סבל, ושמונים אלף איש חוצב בהר, ושלושת אלפים ושש מאות מנצחים ומפקחים עליהם;",
  "2_2": "וישלח שלמה אל חורם (חירם) מלך צור לאמור: 'כפי אשר עשית עם דוד אבי ותשלח לו ארזים לבנות לו בית לשבת בו – עשה עימי!;",
  "2_3": "הנה אני בונה בית לשם ה' אלוהיי, להקדיש לו, להקטיר לפניו קטורת סמים, וללחם המערכת תמיד, ולעולות לבוקר ולערב, לשבתות, לראשי החודשים ולמועדי ה' אלוהינו; חוק עולם הוא זה על ישראל;",
  "2_4": "והבית אשר אני בונה גדול הוא, כי גדול אלוהינו מכל האלוהים;",
  "2_5": "וכי מי יעצור כוח לבנות לו בית, והרי השמים ושמי השמים אינם יכולים להכילו?! ומי אני שאבנה לו בית, כי אם רק להקטיר לפניו קטורת?!;",
  "2_6": "ועתה שלח לי איש חכם ואומן לעשות בזהב, בכסף, בנחושת, בברזל, בארגמן, בכרמיל ובתכלת, ויודע לפתח פיתוחים וגילופים, עם האומנים המומחים אשר עימי ביהודה ובירושלים אשר הכין דוד אבי;",
  "2_7": "ושלח לי עצי ארזים, ברושים ואלגומים מן הלבנון, כי אני ידעתי אשר עבדיך יודעים לכרות עצי לבנון; והנה עבדיי יהיו עם עבדיך;",
  "2_8": "ולהכין לי עצים לרוב עצום, כי הבית אשר אני בונה גדול ומופלא יהיה;",
  "2_9": "והנה לחוטבים כורתי העצים נתתי חיטים מכות לעבדיך כורים עשרים אלף, ושעורים כורים עשרים אלף, ויין בתים עשרים אלף, ושמן בתים עשרים אלף';",
  "2_10": "ויאמר חורם מלך צור במכתב וישלח אל שלמה: 'באהבת ה' את עמו נתנך עליהם מלך!';",
  "2_11": "ויאמר חורם: 'ברוך ה' אלוהי ישראל אשר עשה את השמים ואת הארץ, אשר נתן לדוד המלך בן חכם, יודע שכל ובינה, אשר יבנה בית לה' ובית למלכותו!;",
  "2_12": "ועתה שלחתי איש חכם יודע בינה, את חורם אבי (חורם האומן);",
  "2_13": "בן אישה מן בנות דן ואביו איש צורי, יודע לעשות בזהב, בכסף, בנחושת, בברזל, באבנים ובעצים, בארגמן, בתכלת, בבוץ ובכרמיל, ולפתח כל פיתוח ולחשוב כל מחשבת אומנות אשר תינתן לו, עם חכמיך וחכמי אדוני דוד אביך;",
  "2_14": "ועתה החיטים, השעורים, השמן והיין אשר אמר אדוני – ישלח לעבדיו;",
  "2_15": "ואנחנו נכרות עצים מן הלבנון ככל צורכך, ונביאם לך רפסודות (דוברות צפות) על ים יפו, ואתה תעלה אותם לירושלים';",
  "2_16": "ויספור שלמה את כל האנשים הגרים אשר בארץ ישראל אחרי הספר אשר ספרם דוד אביו; ויימצאו מאה וחמישים אלף ושלושת אלפים ושש מאות;",
  "2_17": "ויעש מהם שבעים אלף סבל, ושמונים אלף חוצב בהר, ושלושת אלפים ושש מאות מנצחים להעביד את העם.",
  "3_1": "ויחל שלמה לבנות את בית ה' בירושלים בהר המוריה, במקום אשר נראה לה' לדוד אביו, אשר הכין במקום דוד בגורן אורנן היבוסי;",
  "3_2": "ויחל לבנות בחודש השני, ביום השני, בשנת ארבע למלכותו;",
  "3_3": "ואלה מידות היסוד שהניח שלמה לבנות את בית האלוהים: האורך אמות במידה הראשונה ששים אמה, ורוחב עשרים אמה;",
  "3_4": "והאולם אשר על פני האורך על פני רוחב הבית – עשרים אמה, והגובה מאה ועשרים אמה; ויצפהו מבפנים זהב טהור;",
  "3_5": "ואת הבית הגדול (ההיכל) חיפה בעץ ברושים, ויחפהו זהב טוב ומובחר, ויעל עליו תבליטי תמרים ושרשרות זהב;",
  "3_6": "ויצף את הבית באבן יקרה לתפארת; והזהב היה זהב פַּרְוָיִם מובחר ונוצץ;",
  "3_7": "ויחף את הבית, הקורות, הסיפים, קירותיו ודלתותיו זהב, ופיתח כרובים על הקירות;",
  "3_8": "ויעש את בית קודש הקודשים: אורכו על פני רוחב הבית עשרים אמה, ורוחבו עשרים אמה; ויחפהו זהב טוב לשש מאות כיכר;",
  "3_9": "ומשקל למסמרים לשקלים חמישים שקלי זהב; ואת העליות חיפה זהב;",
  "3_10": "ויעש בבית קודש הקודשים שני כרובים מעשה צעצועים (פיסול אומנותי), ויצפו אותם זהב;",
  "3_11": "וכנפי הכרובים אורכן עשרים אמה: כנף האחד חמש אמות מגעת לקיר הבית, וכנפו השנייה חמש אמות מגעת לכנף הכרוב האחר;",
  "3_12": "וכנף הכרוב האחד חמש אמות מגעת לקיר הבית, והכנף האחרת חמש אמות דבקה לכנף הכרוב האחר;",
  "3_13": "כנפי הכרובים האלה פרושות עשרים אמה; והמה עומדים על רגליהם ופניהם מועדות אל פנים הבית;",
  "3_14": "ויעש את הפרוכת תכלת, ארגמן, כרמיל ובוץ, ויעל עליה רקמת כרובים;",
  "3_15": "ויעש לפני הבית עמודים שניים, אורך שלושים וחמש אמה, והכותרת אשר על ראשו חמש אמות;",
  "3_16": "ויעש שרשרות בדביר וייתן על ראש העמודים, ויעש רימונים מאה וייתן בשרשרות;",
  "3_17": "ויקם את העמודים על פני ההיכל, אחד מימין ואחד משמאל; ויקרא שם הימני 'יכין', ושם השמאלי 'בועז'.",
  "4_1": "ויעש מזבח נחושת: עשרים אמה אורכו, ועשרים אמה רוחבו, ועשר אמות קומתו;",
  "4_2": "ויעש את הים (כיור ענק) יצוק נחושת: עשר באמה משפתו עד שפתו עגול סביב, וחמש באמה קומתו, וקו שלושים באמה יקיף אותו סביב;",
  "4_3": "ודמות בקרים (בקר מפוסל) תחתיו סביב סביב מקיפים אותו, עשר באמה, מקיפים את הים סביב; שני טורים הבקר יצוקים ביציקתו;",
  "4_4": "עומד על שנים עשר בקר: שלושה פונים צפונה, שלושה פונים ימה, שלושה פונים נגבה, ושלושה פונים מזרחה, והים עליהם מלמעלה; וכל אחוריהם פנימה;",
  "4_5": "ועוביו טפח, ושפתו כמעשה שפת כוס פרח שושן; מחזיק ומכיל שלושת אלפים בתים;",
  "4_6": "ויעש כיורים עשרה, וייתן חמישה מימין וחמישה משמאל לרחצה בהם; את מעשה העולה ידיחו בהם, והים נועד לרחצת הכוהנים בו;",
  "4_7": "ויעש את מנורות הזהב עשר כמשפטן, וייתן בהיכל חמש מימין וחמש משמאל;",
  "4_8": "ויעש שולחנות עשרה וינח בהיכל, חמישה מימין וחמישה משמאל; ויעש מזרקי זהב מאה;",
  "4_9": "ויעש חצר הכוהנים והעזרה הגדולה, ודלתות לעזרה, ודלתותיהם ציפה נחושת;",
  "4_10": "ואת הים נתן מכתף הימנית קדמה מול נגבה;",
  "4_11": "ויעש חורם את הסירים, את היעים ואת המזרקות; ויכל חורם לעשות את המלאכה אשר עשה למלך שלמה בבית האלוהים:",
  "4_12": "עמודים שניים, והגלות והכותרות על ראש העמודים שתיים, והשבכות שתיים לכסות את שתי גלות הכותרות אשר על ראש העמודים;",
  "4_13": "ואת הרימונים ארבע מאות לשתי השבכות, שני טורים רימונים לשבכה האחת, לכסות את שתי גלות הכותרות אשר על פני העמודים;",
  "4_14": "ואת המכונות עשה, ואת הכיורים עשה על המכונות;",
  "4_15": "את הים האחד, ואת הבקר שנים עשר תחתיו;",
  "4_16": "ואת הסירים, את היעים, את המזלגות ואת כל כליהם עשה חורם אביו למלך שלמה לבית ה' נחושת מרוקה ומבריקה;",
  "4_17": "בכיכר הירדן יצקם המלך בעובי האדמה בין סוכות ובין צרדתה;",
  "4_18": "ויעש שלמה כל הכלים האלה לרוב למאוד, כי לא נחקר משקל הנחושת מעוצם הכמות;",
  "4_19": "ויעש שלמה את כל הכלים אשר לבית האלוהים: ואת מזבח הזהב, ואת השולחנות ועליהם לחם הפנים;",
  "4_20": "ואת המנורות ונרותיהן לבערם כמשפט לפני הדביר – זהב סגור;",
  "4_21": "והפרח והנרות והמלקחיים זהב, הוא מכלות זהב מובחר ביותר;",
  "4_22": "והמזמרות, המזרקות, הכפות והמחתות – זהב סגור; ופתח הבית דלתותיו הפנימיות לקודש הקודשים ודלתות הבית להיכל – זהב.",
  "5_1": "ותישלם כל המלאכה אשר עשה שלמה לבית ה'; ויבא שלמה את קודשי דוד אביו: ואת הכסף, ואת הזהב, ואת כל הכלים נתן באוצרות בית האלוהים;",
  "5_2": "אז יקהיל שלמה את זקני ישראל, ואת כל ראשי השבטים נשיאי האבות לבני ישראל לירושלים, להעלות את ארון ברית ה' מעיר דוד היא ציון;",
  "5_3": "וייקהלו אל המלך כל איש ישראל בחג (חג הסוכות) אשר בחודש השביעי;",
  "5_4": "ויבואו כל זקני ישראל; ויישאו הלוויים את הארון;",
  "5_5": "ויעלו את הארון, ואת אוהל מועד, ואת כל כלי הקודש אשר באוהל; העלו אותם הכוהנים והלוויים;",
  "5_6": "והמלך שלמה וכל עדת ישראל הנועדים עליו לפני הארון מזבחים צאן ובקר אשר לא יספרו ולא יימנו מרוב עצום;",
  "5_7": "ויביאו הכוהנים את ארון ברית ה' אל מקומו, אל דביר הבית אל קודש הקודשים, אל תחת כנפי הכרובים;",
  "5_8": "ויהיו הכרובים פורשים כנפיים על מקום הארון, ויכסו הכרובים על הארון ועל בדיו מלמעלה;",
  "5_9": "ויאריכו הבדים, וייראו ראשי הבדים מן הארון על פני הדביר, ולא ייראו החוצה; ויהי שם עד היום הזה;",
  "5_10": "אין בארון כי אם שני הלוחות אשר נתן משה בחורב, אשר כרת ה' עם בני ישראל בצאתם ממצרים;",
  "5_11": "ויהי בצאת הכוהנים מן הקודש – כי כל הכוהנים הנמצאים התקדשו בלא לשמור מחלקות קבועות;",
  "5_12": "והלוויים המשוררים לכולם – לאסף, להימן, לידותון, ולבניהם ולאחיהם מלובשים בוץ במצלתיים, בנבלים ובכינורות, עומדים מזרח למזבח, ועימהם כוהנים למאה ועשרים מחצצרים בחצוצרות;",
  "5_13": "ויהי כאחד למחצצרים ולמשוררים להשמיע קול אחד להלל ולהודות לה', וכהרים קול בחצוצרות ובמצלתיים ובכלי השיר ובהלל לה' כי טוב כי לעולם חסדו – והבית נמלא ענן, בית ה';",
  "5_14": "ולא יכלו הכוהנים לעמוד לשרת מפני הענן, כי מלא כבוד ה' את בית האלוהים.",
  "6_1": "אז אמר שלמה: 'ה' אמר לשכון בערפל ובחשאי הכבוד;",
  "6_2": "ואני בניתי בית זבול מפואר לך, ומכון לשבתך עולמים!';",
  "6_3": "ויסב המלך את פניו ויברך את כל קהל ישראל, וכל קהל ישראל עומד ביראת כבוד;",
  "6_4": "ויאמר: 'ברוך ה' אלוהי ישראל אשר דיבר בפיו את דוד אבי, ובידיו מילא וקיים לאמור:",
  "6_5": "\"מן היום אשר הוצאתי את עמי מארץ מצרים לא בחרתי בעיר מכל שבטי ישראל לבנות בית להיות שמי שם, ולא בחרתי באיש להיות נגיד על עמי ישראל;",
  "6_6": "ואבחר בירושלים להיות שמי שם, ואבחר בדוד להיות על עמי ישראל!\";",
  "6_7": "ויהי עם לבב דוד אבי לבנות בית לשם ה' אלוהי ישראל;",
  "6_8": "ויאמר ה' אל דוד אבי: \"יען אשר היה עם לבבך לבנות בית לשמי – הטיבות כי היה עם לבבך;",
  "6_9": "רק לא אתה תבנה הבית, כי בנך היוצא מחלציך הוא יבנה הבית לשמי!\";",
  "6_10": "ויקם ה' את דברו אשר דיבר; ואקום תחת דוד אבי ואשב על כיסא ישראל כאשר דיבר ה', ואבנה הבית לשם ה' אלוהי ישראל;",
  "6_11": "ואשים שם את הארון אשר שם ברית ה' אשר כרת עם בני ישראל';",
  "6_12": "ויעמוד שלמה לפני מזבח ה' נגד כל קהל ישראל, ויפרוש כפיו בתפילה;",
  "6_13": "כי עשה שלמה כיור נחושת ויתנהו בתוך העזרה, חמש אמות אורכו וחמש אמות רוחבו ושלוש אמות קומתו, ויעמוד עליו ויכרע על ברכיו נגד כל קהל ישראל ויפרוש כפיו השמימה;",
  "6_14": "ויאמר: 'ה' אלוהי ישראל, אין כמוך אלוהים בשמים ובארץ, שומר הברית והחסד לעבדיך ההולכים לפניך בכל לבם!;",
  "6_15": "אשר שמרת לעבדך דוד אבי את אשר דיברת לו; ותדבר בפיך ובידך מילאת כיום הזה!;",
  "6_16": "ועתה ה' אלוהי ישראל, שמור לעבדך דוד אבי את אשר דיברת לו לאמור: \"לא ייכרת לך איש מלפניי יושב על כיסא ישראל, רק אם ישמרו בניך את דרכם ללכת בתורתי כאשר הלכת לפניי!\";",
  "6_17": "ועתה ה' אלוהי ישראל, ייאמן נא דברך אשר דיברת לעבדך לדוד!;",
  "6_18": "כי האמנם יישב אלוהים את האדם על הארץ?! הנה שמים ושמי השמים לא יכלכלוך, אף כי הבית הזה אשר בניתי!;",
  "6_19": "ופנית אל תפילת עבדך ואל תחינתו ה' אלוהיי, לשמוע אל הרינה ואל התפילה אשר עבדך מתפלל לפניך!;",
  "6_20": "להיות עיניך פקוחות אל הבית הזה יומם ולילה, אל המקום אשר אמרת לשום שמך שם, לשמוע אל התפילה אשר יתפלל עבדך אל המקום הזה!;",
  "6_21": "ושמעת אל תחנוני עבדך ועמך ישראל אשר יתפללו אל המקום הזה; ואתה תשמע ממקום שבתך מן השמים, ושמעת וסלחת!;",
  "6_22": "אם יחטא איש לרעהו, ונשא בו אלה להשביעו, ובא אלה לפני מזבחך בבית הזה –",
  "6_23": "ואתה תשמע מן השמים ועשית ושפטת את עבדיך, להשיב לרשע לתת דרכו בראשו, ולהצדיק צדיק לתת לו כצדקתו!;",
  "6_24": "ואם יינגף עמך ישראל לפני אויב כי יחטאו לך, ושבו והודו את שמך והתפללו והתחננו לפניך בבית הזה –",
  "6_25": "ואתה תשמע מן השמים וסלחת לחטאת עמך ישראל, והשבותם אל האדמה אשר נתת להם ולאבותיהם!;",
  "6_26": "בהיעצר השמים ולא יהיה מטר כי יחטאו לך, והתפללו אל המקום הזה והודו את שמך ומחטאתם ישובו כי תענם –",
  "6_27": "ואתה תשמע השמים וסלחת לחטאת עבדיך ועמך ישראל, כי תורם אל הדרך הטובה אשר ילכו בה, ונתתה מטר על ארצך אשר נתת לעמך לנחלה!;",
  "6_28": "רעב כי יהיה בארץ, דבר כי יהיה, שידפון וירקון, ארבה וחסיל כי יהיה, כי יצר לו אויביו בארץ שעריו, כל נגע וכל מחלה –",
  "6_29": "כל תפילה, כל תחינה אשר תהיה לכל אדם ולכל עמך ישראל, אשר יידעו איש נגעו ומכאובו ופרש כפיו אל הבית הזה –",
  "6_30": "ואתה תשמע מן השמים מכון שבתך וסלחת, ונתת לאיש ככל דרכיו אשר תדע את לבבו (כי אתה לבדך ידעת את לבב בני האדם);",
  "6_31": "למען ייראוך ללכת בדרכיך כל הימים אשר הם חיים על פני האדמה אשר נתת לאבותינו!;",
  "6_32": "וגם אל הנוכרי אשר לא מעמך ישראל הוא, ובא מארץ רחוקה למען שמך הגדול וידך החזקה וזרועך הנטויה, ובאו והתפללו אל הבית הזה –",
  "6_33": "אתה תשמע מן השמים ממכון שבתך, ועשית ככל אשר יקרא אליך הנוכרי; למען יידעו כל עמי הארץ את שמך וליראה אותך כעמך ישראל, ולדעת כי שמך נקרא על הבית הזה אשר בניתי!;",
  "6_34": "כי ייצא עמך למלחמה על אויביו בדרך אשר תשלחם, והתפללו אליך דרך העיר הזאת אשר בחרת בה והבית אשר בניתי לשמך –",
  "6_35": "ושמעת מן השמים את תפילתם ואת תחינתם, ועשית משפטם!;",
  "6_36": "כי יחטאו לך – כי אין אדם אשר לא יחטא – ואנפת בם ונתתם לפני אויב, ושבום שוביהם אל ארץ רחוקה או קרובה;",
  "6_37": "והשיבו אל לבבם בארץ אשר נשבו שם, ושבו והתחננו אליך בארץ שבים לאמור: \"חטאנו, העווינו והרשענו!\";",
  "6_38": "ושבו אליך בכל לבם ובכל נפשם בארץ שבים אשר שבו אותם, והתפללו דרך ארצם אשר נתת לאבותיהם והעיר אשר בחרת ולבית אשר בניתי לשמך –",
  "6_39": "ושמעת מן השמים ממכון שבתך את תפילתם ואת תחינותיהם, ועשית משפטם, וסלחת לעמך אשר חטאו לך!;",
  "6_40": "עתה אלוהיי, יהיו נא עיניך פקוחות ואוזניך קשובות לתפילת המקום הזה!;",
  "6_41": "ועתה קומה ה' אלוהים למנוחתך, אתה וארון עוזך; כוהניך ה' אלוהים יילבשו תשועה, וחסידיך ישמחו בטוב!;",
  "6_42": "ה' אלוהים, אל תשב פני משיחך; זכרה לחסדי דוד עבדך!'.",
  "7_1": "וככלות שלמה להתפלל, והאש ירדה מן השמים ותאכל העולה והזבחים; וכבוד ה' מלא את הבית;",
  "7_2": "ולא יכלו הכוהנים לבוא אל בית ה', כי מלא כבוד ה' את בית ה';",
  "7_3": "וכל בני ישראל רואים ברדת האש וכבוד ה' על הבית, ויכרעו אפיים ארצה על הרצפה וישתחוו והודות לה' כי טוב כי לעולם חסדו;",
  "7_4": "והמלך וכל העם זובחים זבח לפני ה';",
  "7_5": "ויזבח המלך שלמה את זבח הבקר עשרים ושניים אלף, וצאן מאה ועשרים אלף; ויחנכו את בית האלוהים המלך וכל העם;",
  "7_6": "והכוהנים על משמרותיהם עומדים, והלוויים בכלי שיר ה' אשר עשה דוד המלך להודות לה' כי לעולם חסדו בהלל דוד בידם; והכוהנים מחצצרים נגדם, וכל ישראל עומדים;",
  "7_7": "ויקדש שלמה את תוך החצר אשר לפני בית ה', כי עשה שם העולות ואת חלבי השלמים, כי מזבח הנחושת אשר עשה שלמה לא יכול היה להכיל את העולה ואת המנחה ואת החלבים מרובם העצום;",
  "7_8": "ויעש שלמה את החג בעת ההיא שבעת ימים, וכל ישראל עימו, קהל גדול מאוד מלבוא חמת עד נחל מצרים;",
  "7_9": "ויעשו ביום השמיני עצרת; כי חנוכת המזבח עשו שבעת ימים, ואת חג הסוכות שבעת ימים;",
  "7_10": "וביום עשרים ושלושה לחודש השביעי שילח את העם לאוהליהם, שמחים וטובי לב על הטובה אשר עשה ה' לדוד ולשלמה ולישראל עמו;",
  "7_11": "ויכל שלמה את בית ה' ואת בית המלך; ואת כל הבא על לב שלמה לעשות בבית ה' ובביתו הצליח במלואו;",
  "7_12": "ויירא ה' אל שלמה בלילה, ויאמר לו: 'שמעתי את תפילתך, ובחרתי במקום הזה לי לבית זבח;",
  "7_13": "הן אעצור השמים ולא יהיה מטר, והן אצווה על חגב לאכול הארץ, ואם אשלח דבר בעמי –",
  "7_14": "וייכנעו עמי אשר נקרא שמי עליהם ויתפללו ויבקשו פניי וישובו מדרכיהם הרעים – ואני אשמע מן השמים, ואסלח לחטאתם, וארפא את ארצם!;",
  "7_15": "עתה עיניי יהיו פקוחות ואוזניי קשובות לתפילת המקום הזה;",
  "7_16": "ועתה בחרתי והקדשתי את הבית הזה להיות שמי שם עד עולם, והיו עיניי ולבי שם כל הימים;",
  "7_17": "ואתה אם תלך לפניי כאשר הלך דוד אביך, ולעשות ככל אשר ציוויתיך וחוקיי ומשפטיי תשמור –",
  "7_18": "והקימותי את כיסא מלכותך כאשר כרתי לדוד אביך לאמור: \"לא ייכרת לך איש מושל בישראל!\";",
  "7_19": "ואם תשובו אתם ועזבתם חוקותיי ומצוותיי אשר נתתי לפניכם, והלכתם ועבדתם אלוהים אחרים והשתחויתם להם –",
  "7_20": "ונתשתים מעל אדמתי אשר נתתי להם, ואת הבית הזה אשר הקדשתי לשמי אשליך מעל פניי, ואתננו למשל ולשנינה בכל העמים;",
  "7_21": "והבית הזה אשר היה עליון, כל עובר עליו יישום ויאמר: \"על מה עשה ה' ככה לארץ הזאת ולבית הזה?!\";",
  "7_22": "ואמרו: \"על אשר עזבו את ה' אלוהי אבותיהם אשר הוציאם מארץ מצרים, ויחזיקו באלוהים אחרים וישתחוו להם ויעבדום; על כן הביא עליהם את כל הרעה הזאת!\".",
  "8_1": "ויהי מקץ עשרים שנה אשר בנה שלמה את בית ה' ואת ביתו שלו;",
  "8_2": "והערים אשר נתן חורם לשלמה – בנה אותם שלמה ויושב שם את בני ישראל;",
  "8_3": "וילך שלמה חמת צובה ויחזק עליה;",
  "8_4": "ויבן את תדמור במדבר, ואת כל ערי המסכנות אשר בנה בחמת;",
  "8_5": "ויבן את בית חורון העליון ואת בית חורון התחתון ערי מצור חומות דלתות ובריח;",
  "8_6": "ואת בעלת, ואת כל ערי המסכנות אשר היו לשלמה, ואת כל ערי הרכב ואת ערי הפרשים, ואת כל חשק שלמה אשר חשק לבנות בירושלים ובלבנון ובכל ארץ ממשלתו;",
  "8_7": "כל העם הנותר מן החיתי, והאמורי, והפריזי, והחיווי, והיבוסי אשר לא מישראל המה –",
  "8_8": "מן בניהם אשר נותרו אחריהם בארץ אשר לא כילום בני ישראל, ויעלם שלמה למס עובד עד היום הזה;",
  "8_9": "ומן בני ישראל לא נתן שלמה עבדים למלאכתו, כי המה אנשי מלחמה ושרי שלישיו ושרי רכבו ופרשיו;",
  "8_10": "ואלה שרי הנציבים אשר למלך שלמה: מאתיים וחמישים הרודים בעם;",
  "8_11": "ואת בת פרעה העלה שלמה מעיר דוד לבית אשר בנה לה, כי אמר: 'לא תשב אישה לי בבית דוד מלך ישראל, כי קודש המה המקומות אשר באה אליהם ארון ה'!';",
  "8_12": "אז העלה שלמה עולות לה' על מזבח ה' אשר בנה לפני האולם;",
  "8_13": "ובדבר יום ביומו להעלות כמצוות משה לשבתות, ולחדשים, ולמועדות שלוש פעמים בשנה: בחג המצות, ובחג השבועות, ובחג הסוכות;",
  "8_14": "ויעמד כמשפט דוד אביו את מחלקות הכוהנים על עבודתם, והלוויים על משמרותם להלל ולשרת נגד הכוהנים לדבר יום ביומו, והשוערים במחלקותם לשער ושער; כי כן הייתה מצוות דוד איש האלוהים;",
  "8_15": "ולא סרו ממצוות המלך על הכוהנים והלוויים לכל דבר ולאוצרות;",
  "8_16": "ותיכון כל מלאכת שלמה עד היום מוסד בית ה' ועד כלותו; שלם בית ה';",
  "8_17": "אז הלך שלמה לעציון גבר ואל אילות על שפת הים בארץ אדום;",
  "8_18": "וישלח לו חורם ביד עבדיו אוניות ועבדים יודעי ים, ויבואו עם עבדי שלמה אופירה, וייקחו משם ארבע מאות וחמישים כיכר זהב ויביאו אל המלך שלמה.",
  "9_1": "ומלכת שבא שמעה את שמע שלמה, ותבוא לנסות את שלמה בחידות בירושלים בחיל כבד מאוד, וגמלים נושאים בשמים וזהב לרוב ואבן יקרה; ותבוא אל שלמה ותדבר עימו את כל אשר היה עם לבבה;",
  "9_2": "ויגד לה שלמה את כל דבריה, ולא נעלם דבר משלמה אשר לא הגיד לה;",
  "9_3": "ותרא מלכת שבא את חכמת שלמה, והבית אשר בנה;",
  "9_4": "ומאכל שולחנו, ומושב עבדיו, ומעמד משרתיו ומלבושיהם, ומשקיו ומלבושיהם, ועליתו אשר יעלה בית ה' – ולא היה בה עוד רוח מרוב התפעלות;",
  "9_5": "ותאמר אל המלך: 'אמת היה הדבר אשר שמעתי בארצי על דבריך ועל חכמתך!;",
  "9_6": "ולא האמנתי לדבריהם עד אשר באתי ותראינה עיניי, והנה לא הוגד לי חצי מרבית חכמתך; יספת על השמועה אשר שמעתי!;",
  "9_7": "אשרי אנשיך ואשרי עבדיך אלה העומדים לפניך תמיד ושומעים את חכמתך!;",
  "9_8": "יהי ה' אלוהיך ברוך אשר חפץ בך לתתך על כיסאו למלך לה' אלוהיך; באהבת אלוהיך את ישראל להעמידו לעולם, וייתנך עליהם למלך לעשות משפט וצדקה!';",
  "9_9": "ותיתן למלך מאה ועשרים כיכר זהב, ובשמים לרוב מאוד ואבן יקרה; ולא היה כבושם ההוא אשר נתנה מלכת שבא למלך שלמה;",
  "9_10": "וגם עבדי חורם ועבדי שלמה אשר הביאו זהב מאופיר, הביאו עצי אלגומים ואבן יקרה;",
  "9_11": "ויעש המלך את עצי האלגומים מסילות לבית ה' ולבית המלך, וכינורות ונבלים למשוררים; ולא נראו כהם לפנים בארץ יהודה;",
  "9_12": "והמלך שלמה נתן למלכת שבא את כל חפצה אשר שאלה, מלבד תמורה לאשר הביאה אל המלך; ותהפוך ותלך לארצה היא ועבדיה;",
  "9_13": "ויהי משקל הזהב אשר בא לשלמה בשנה אחת: שש מאות ושישים ושש כיכר זהב;",
  "9_14": "מלבד מאנשי התיירים והסוחרים מביאים, וכל מלכי ערב ופחות הארץ מביאים זהב וכסף לשלמה;",
  "9_15": "ויעש המלך שלמה מאתיים צנה (מגן גדול) זהב שחוט; שש מאות שקלי זהב שחוט יעלה על הצנה האחת;",
  "9_16": "ושלוש מאות מגנים זהב שחוט; שלוש מאות שקלי זהב יעלה על המגן האחד; וייתנם המלך בבית יער הלבנון;",
  "9_17": "ויעש המלך כיסא שן גדול, ויצפהו זהב טהור;",
  "9_18": "ושש מעלות לכיסא וכבש בזהב לכיסא מאחזים, וידות מזה ומזה על מקום השבת, ושניים אריות עומדים אצל הידות;",
  "9_19": "ושנים עשר אריות עומדים שם על שש המעלות מזה ומזה; לא נעשה כן לכל ממלכה;",
  "9_20": "וכל כלי משקה המלך שלמה זהב, וכל כלי בית יער הלבנון זהב סגור; אין כסף נחשב בימי שלמה למאומה;",
  "9_21": "כי אוניות למלך הולכות תרשיש עם עבדי חורם; אחת לשלוש שנים תבואנה אוניות תרשיש נושאות זהב וכסף, שנהבים, וקופים ותוכיים;",
  "9_22": "ויגדל המלך שלמה מכל מלכי הארץ לעושר ולחכמה;",
  "9_23": "וכל מלכי הארץ מבקשים את פני שלמה, לשמוע את חכמתו אשר נתן האלוהים בלבו;",
  "9_24": "והמה מביאים איש מנחתו: כלי כסף וכלי זהב ושמלות, נשק ובשמים, סוסים ופרדים, דבר שנה בשנה;",
  "9_25": "ויהי לשלמה ארבעת אלפים ארוות סוסים ומרכבות, ושנים עשר אלף פרשים; ויניחם בערי הרכב ועם המלך בירושלים;",
  "9_26": "ויהי מושל בכל המלכים מן הנהר (פרת) ועד ארץ פלשתים ועד גבול מצרים;",
  "9_27": "וייתן המלך את הכסף בירושלים כאבנים, ואת הארזים נתן כשקמים אשר בשפלה לרוב;",
  "9_28": "ומוציאים סוסים לשלמה ממצרים ומכל הארצות;",
  "9_29": "ושאר דברי שלמה הראשונים והאחרונים, הלא הם כתובים על דברי נתן הנביא, ועל נבואת אחיה השילוני, ובחזות יעדו (עידו) החוזה על ירבעם בן נבט;",
  "9_30": "וימלוך שלמה בירושלים על כל ישראל ארבעים שנה;",
  "9_31": "וישכב שלמה עם אבותיו, ויקברוהו בעיר דוד אביו; וימלוך רחבעם בנו תחתיו.",
  "10_1": "וילך רחבעם שכמה, כי שכם באו כל ישראל להמליך אותו;",
  "10_2": "ויהי כשמוע ירבעם בן נבט, והוא במצרים אשר ברח מפני שלמה המלך, וישב ירבעם ממצרים;",
  "10_3": "וישלחו ויקראו לו; ויבוא ירבעם וכל ישראל, וידברו אל רחבעם לאמור:",
  "10_4": "'אביך הקשה את עולנו; ועתה הקל מעבודת אביך הקשה ומעולו הכבד אשר נתן עלינו, ונעבדך!';",
  "10_5": "ויאמר להם: 'עוד שלושת ימים ושובו אליי!'; וילך העם;",
  "10_6": "וייוועץ המלך רחבעם את הזקנים אשר היו עומדים לפני שלמה אביו בהיותו חי לאמור: 'איך אתם נועצים להשיב לעם הזה דבר?';",
  "10_7": "וידברו אליו לאמור: 'אם תהיה לטוב להעם הזה ורציתם ודיברת אליהם דברים טובים – והיו לך עבדים כל הימים!';",
  "10_8": "ויעזוב את עצת הזקנים אשר יעצוהו, וייוועץ את הילדים (הצעירים) אשר גדלו עימו העומדים לפניו;",
  "10_9": "ויאמר להם: 'מה אתם נועצים ונשיב דבר את העם הזה אשר דיברו אליי לאמור: \"הקל מן העול אשר נתן אביך עלינו\"?';",
  "10_10": "וידברו עימו הילדים אשר גדלו עימו לאמור: 'כה תאמר לעם אשר דיברו אליך לאמור: \"אביך הכביד את עולנו ואתה הקל מעלינו\", כה תאמר אליהם: \"קטני עבה ממותני אבי!;",
  "10_11": "ועתה, אבי העמיס עליכם עול כבד – ואני אוסיף על עולכם; אבי ייסר אתכם בשוטים – ואני אייסר בעקרבים!\";",
  "10_12": "ויבוא ירבעם וכל העם אל רחבעם ביום השלישי, כאשר דיבר המלך לאמור: 'שובו אליי ביום השלישי!';",
  "10_13": "ויענם המלך קשות; ויעזוב המלך רחבעם את עצת הזקנים;",
  "10_14": "וידבר אליהם כעצת הילדים לאמור: 'אכביד את עולכם ואני אוסיף עליו; אבי ייסר אתכם בשוטים ואני בעקרבים!';",
  "10_15": "ולא שמע המלך אל העם, כי הייתה נסיבה מאת האלוהים למען הקים ה' את דברו אשר דיבר ביד אחיה השילוני אל ירבעם בן נבט;",
  "10_16": "וכל ישראל כי לא שמע המלך להם, וישיבו העם את המלך לאמור: 'מה לנו חלק בדוד ולא נחלה בבן ישי?! איש לאוהליך ישראל! עתה ראה ביתך דוד!'; וילך כל ישראל לאוהליו;",
  "10_17": "ובני ישראל היושבים בערי יהודה – וימלוך עליהם רחבעם;",
  "10_18": "וישלח המלך רחבעם את הדורם אשר על המס, וירגמו בו בני ישראל אבן וימת; והמלך רחבעם התאמץ לעלות במרכבה לנוס ירושלים;",
  "10_19": "ויפשעו ישראל בבית דוד עד היום הזה.",
  "11_1": "ויבוא רחבעם ירושלים, ויקהל את בית יהודה ובנימין מאה ושמונים אלף בחור עושה מלחמה להילחם עם ישראל, להשיב את הממלכה לרחבעם;",
  "11_2": "ויהי דבר ה' אל שמעיהו איש האלוהים לאמור:",
  "11_3": "'אמור אל רחבעם בן שלמה מלך יהודה, ואל כל ישראל ביהודה ובנימין לאמור:",
  "11_4": "כה אמר ה': לא תעלו ולא תילחמו עם אחיכם! שובו איש לביתו, כי מאיתי נהיה הדבר הזה!'; וישמעו את דברי ה', וישובו מלכת על ירבעם;",
  "11_5": "ויישב רחבעם בירושלים, ויבן ערים למצור ביהודה;",
  "11_6": "ויבן את בית לחם, ואת עיטם, ואת תקוע;",
  "11_7": "ואת בית צור, ואת שוכו, ואת עדולם;",
  "11_8": "ואת גת, ואת מרשה, ואת זיף;",
  "11_9": "ואת אדוריים, ואת לכיש, ואת עזקה;",
  "11_10": "ואת צרעה, ואת איילון, ואת חברון אשר ביהודה ובבנימין ערי מצורות;",
  "11_11": "ויחזק את המצודות, וייתן בהן נגידים ומפקדים, ואוצרות מאכל, שמן ויין;",
  "11_12": "ובכל עיר ועיר צנות ורמחים, ויחזקם למאוד מאוד; ויהיו לו יהודה ובנימין;",
  "11_13": "והכוהנים והלוויים אשר בכל ישראל התייצבו עליו מכל גבולם;",
  "11_14": "כי עזבו הלוויים את מגרשיהם ואחוזתם וילכו ליהודה ולירושלים, כי הזניחם ירבעם ובניו מכהן לה';",
  "11_15": "ויעמד לו כוהנים לבמות, ולשעירים (שדים), ולעגלים אשר עשה;",
  "11_16": "ואחריהם מכל שבטי ישראל, הנותנים את לבבם לבקש את ה' אלוהי ישראל, באו ירושלים לזבוח לה' אלוהי אבותיהם;",
  "11_17": "ויחזקו את מלכות יהודה ויאמצו את רחבעם בן שלמה לשנים שלוש, כי הלכו בדרך דוד ושלמה לשנים שלוש;",
  "11_18": "וייקח לו רחבעם אישה את מחלת בת ירימות בן דוד, אביחיל בת אליאב בן ישי;",
  "11_19": "ותלד לו בנים: את יעוש, ואת שמריה, ואת זהם;",
  "11_20": "ואחריה לקח את מעכה בת אבשלום; ותלד לו את אביה, ואת עתי, ואת זיזא, ואת שלומית;",
  "11_21": "ויאהב רחבעם את מעכה בת אבשלום מכל נשיו ופילגשיו, כי נשים שמונה עשרה נשא ופילגשים שישים, ויולד עשרים ושמונה בנים ושישים בנות;",
  "11_22": "ויעמד לראש רחבעם את אביה בן מעכה לנגיד באחיו, כי להמליכו;",
  "11_23": "ויבן ויפרוץ מכל בניו לכל ארצות יהודה ובנימין לכל ערי המצורות, וייתן להם מזון לרוב וישאל המון נשים.",
  "12_1": "ויהי כהכין מלכות רחבעם וכחזקתו, עזב את תורת ה' וכל ישראל עימו;",
  "12_2": "ויהי בשנה החמישית למלך רחבעם, עלה שישק מלך מצרים על ירושלים – כי מעלו בה';",
  "12_3": "באלף ומאתיים רכב ובשישים אלף פרשים, ואין מספר לעם אשר באו עימו ממצרים: לובים, סוכיים וכושים;",
  "12_4": "וילכוד את ערי המצורות אשר ליהודה, ויבוא עד ירושלים;",
  "12_5": "ושמעיה הנביא בא אל רחבעם ושרי יהודה אשר נאספו אל ירושלים מפני שישק, ויאמר להם: 'כה אמר ה': אתם עזבתם אותי, ואף אני עזבתי אתכם ביד שישק!';",
  "12_6": "וייכנעו שרי ישראל והמלך, ויאמרו: 'צדיק ה'!';",
  "12_7": "ובראות ה' כי נכנעו, היה דבר ה' אל שמעיה לאמור: 'נכנעו, לא אשחיתם! ונתתי להם כמעט לפליטה, ולא תיתך חמתי בירושלים ביד שישק;",
  "12_8": "כי יהיו לו לעבדים, ויידעו עבודתי ועבודת ממלכות הארצות!';",
  "12_9": "ויעל שישק מלך מצרים על ירושלים, וייקח את אוצרות בית ה' ואת אוצרות בית המלך, ואת הכול לקח; וייקח את מגני הזהב אשר עשה שלמה;",
  "12_10": "ויעש המלך רחבעם תחתיהם מגני נחושת, והפקיד על יד שרי הרצים השומרים פתח בית המלך;",
  "12_11": "ויהי מדי בוא המלך בית ה' באו הרצים ונשאום, והשיבום אל תא הרצים;",
  "12_12": "ובהיכנעו שב ממנו אף ה' ולא להשחית לכלה; וגם ביהודה היה דברים טובים;",
  "12_13": "ויתחזק המלך רחבעם בירושלים וימלוך; כי בן ארבעים ואחת שנה רחבעם במלכו, ושבע עשרה שנה מלך בירושלים העיר אשר בחר ה' לשום את שמו שם מכל שבטי ישראל; ושם אמו נעמה העמונית;",
  "12_14": "ויעש הרע, כי לא הכין לבבו לדרוש את ה';",
  "12_15": "ודברי רחבעם הראשונים והאחרונים, הלא הם כתובים בדברי שמעיה הנביא ועדו החוזה להתייחס; ומלחמות רחבעם וירבעם כל הימים;",
  "12_16": "וישכב רחבעם עם אבותיו, וייקבר בעיר דוד; וימלוך אביה בנו תחתיו.",
  "13_1": "בשנת שמונה עשרה למלך ירבעם, מלך אביה על יהודה;",
  "13_2": "שלוש שנים מלך בירושלים, ושם אמו מיכיהו בת אוריאל מן גבעה; ומלחמה הייתה בין אביה ובין ירבעם;",
  "13_3": "ויאסור אביה את המלחמה בחיל גיבורי מלחמה ארבע מאות אלף איש בחור; וירבעם ערך עימו מלחמה בשמונה מאות אלף איש בחור גיבור חיל;",
  "13_4": "ויקם אביה מעל להר צמרים אשר בהר אפרים, ויאמר: 'שמעוני ירבעם וכל ישראל!;",
  "13_5": "הלא לכם לדעת כי ה' אלוהי ישראל נתן את הממלכה לדוד על ישראל לעולם, לו ולבניו ברית מלח (ברית נצחית קיימת)!;",
  "13_6": "ויקם ירבעם בן נבט עבד שלמה בן דוד, וימרוד על אדוניו;",
  "13_7": "וייקבצו עליו אנשים ריקים בני בליעל ויתאמצו על רחבעם בן שלמה, ורחבעם היה נער ורך לבב ולא התחזק לפניהם;",
  "13_8": "ועתה אתם אומרים להתחזק לפני ממלכת ה' ביד בני דוד, ואתם המון רב, ועמכם עגלי זהב אשר עשה לכם ירבעם לאלוהים!;",
  "13_9": "הלא הדחתם את כוהני ה' את בני אהרון והלוויים, ותעשו לכם כוהנים כעמי הארצות – כל הבא למלא ידו בפר בן בקר ואילים שבעה והיה כוהן ללא אלוהים?!;",
  "13_10": "ואנחנו, ה' אלוהינו ולא עזבנוהו, וכוהנים משרתים לה' בני אהרון והלוויים במלאכה;",
  "13_11": "ומקטירים לה' עולות בבוקר בבוקר ובערב בערב וקטורת סמים, ומערכת לחם על השולחן הטהור, ומנורת הזהב ונרותיה לבער בערב בערב; כי שומרים אנחנו את משמרת ה' אלוהינו, ואתם עזבתם אותו!;",
  "13_12": "והנה עימנו בראש האלוהים וכוהניו וחצוצרות התרועה להריע עליכם; בני ישראל, אל תילחמו עם ה' אלוהי אבותיכם כי לא תצליחו!';",
  "13_13": "וירבעם הסב את המארב לבוא מאחוריהם; ויהיו לפני יהודה, והמארב מאחוריהם;",
  "13_14": "ויפנו יהודה והנה להם המלחמה פנים ואחור, ויצעקו לה'; והכוהנים מחצצרים בחצוצרות;",
  "13_15": "ויריעו איש יהודה; ויהי בהריע איש יהודה, והאלוהים נגף את ירבעם וכל ישראל לפני אביה ויהודה;",
  "13_16": "וינוסו בני ישראל מפני יהודה, וייתנם אלוהים בידם;",
  "13_17": "ויכו בהם אביה ועמו מכה רבה; וייפלו חללים מישראל חמש מאות אלף איש בחור;",
  "13_18": "וייכנעו בני ישראל בעת ההיא, ויאמצו בני יהודה כי נשענו על ה' אלוהי אבותיהם;",
  "13_19": "וירדוף אביה אחרי ירבעם וילכוד ממנו ערים: את בית אל ואת בנותיה, ואת ישנה ואת בנותיה, ואת עפרון ואת בנותיה;",
  "13_20": "ולא עצר כוח ירבעם עוד בימי אביה; ויגפהו ה' וימת;",
  "13_21": "ויתחזק אביה, ויישא לו נשים ארבע עשרה, ויולד עשרים ושניים בנים ושש עשרה בנות;",
  "13_22": "ויתר דברי אביה ודרכיו ודבריו כתובים במדרש הנביא עידו;",
  "13_23": "וישכב אביה עם אבותיו ויקברו אותו בעיר דוד, וימלוך אסא בנו תחתיו; בימיו שקטה הארץ עשר שנים.",
  "14_1": "ויעש אסא הטוב והישר בעיני ה' אלוהיו;",
  "14_2": "ויסר את מזבחות הנכר והבמות, וישבר את המצבות ויגדע את האשרים;",
  "14_3": "ויאמר ליהודה לדרוש את ה' אלוהי אבותיהם, ולעשות התורה והמצווה;",
  "14_4": "ויסר מכל ערי יהודה את הבמות ואת החמנים (מזבחות השמש), ותשקוט הממלכה לפניו;",
  "14_5": "ויבן ערי מצורה ביהודה, כי שקטה הארץ ואין עימו מלחמה בשנים האלה, כי הניח ה' לו;",
  "14_6": "ויאמר ליהודה: 'נבנה את הערים האלה ונסב חומה ומגדלים, דלתות ובריחים, עודנו הארץ לפנינו כי דרשנו את ה' אלוהינו, דרשנו וינח לנו מסביב!'; ויבנו ויצליחו;",
  "14_7": "ויהי לאסא חיל נושא צנה ורומח מיהודה שלוש מאות אלף, ומבנימין נושאי מגן ודורכי קשת מאתיים ושמונים אלף; כל אלה גיבורי חיל;",
  "14_8": "וייצא אליהם זרח הכושי בחיל אלף אלפים (מיליון) ומרכבות שלוש מאות, ויבוא עד מרשה;",
  "14_9": "וייצא אסא לפניו, ויערכו מלחמה בגיא צפתה למרשה;",
  "14_10": "ויקרא אסא אל ה' אלוהיו ויאמר: 'ה', אין עמך לעזור בין רב לאין כוח! עזרנו ה' אלוהינו כי עליך נשעננו ובשמך באנו על ההמון הזה; ה' אלוהינו אתה, אל יעצור עמך אנוש!';",
  "14_11": "ויגוף ה' את הכושים לפני אסא ולפני יהודה, וינוסו הכושים;",
  "14_12": "וירדפם אסא והעם אשר עימו עד לגרר, וייפול מכושים לאין להם מחיה כי נשברו לפני ה' ולפני מחנהו; וישאו שלל הרבה מאוד;",
  "14_13": "ויכו את כל הערים סביבות גרר כי היה פחד ה' עליהם, ויבוזו את כל הערים כי ביזה רבה הייתה בהם;",
  "14_14": "וגם אוהלי מקנה היכו, וישבו צאן לרוב וגמלים, וישובו ירושלים.",
  "15_1": "ועזריהו בן עודד הייתה עליו רוח אלוהים;",
  "15_2": "וייצא לפני אסא ויאמר לו: 'שמעוני אסא וכל יהודה ובנימין! ה' עימכם בהיותכם עימו; ואם תדרשוהו – יימצא לכם, ואם תעזבוהו – יעזוב אתכם!;",
  "15_3": "וימים רבים לישראל ללא אלוהי אמת, וללא כוהן מורה, וללא תורה;",
  "15_4": "וישב בצר לו על ה' אלוהי ישראל, ויבקשוהו ויימצא להם;",
  "15_5": "ובעתים ההם אין שלום ליוצא ולבא, כי מהומות רבות על כל יושבי הארצות;",
  "15_6": "וכותתו גוי בגוי ועיר בעיר, כי אלוהים הממם בכל צרה;",
  "15_7": "ואתם חזקו ואל ירפו ידיכם, כי יש שכר לפעולתכם!';",
  "15_8": "וכשמוע אסא הדברים האלה והנבואה עודד הנביא, התחזק ויעבר השיקוצים מכל ארץ יהודה ובנימין ומן הערים אשר לכד מהר אפרים, ויחדש את מזבח ה' אשר לפני אולם ה';",
  "15_9": "וייקבץ את כל יהודה ובנימין, והגרים עימהם מאפרים ומנשה ומשמעון, כי נפלו עליו מישראל לרוב בראותם כי ה' אלוהיו עימו;",
  "15_10": "וייקבצו ירושלים בחודש השלישי (סיוון, חג השבועות) לשנת חמש עשרה למלכות אסא;",
  "15_11": "ויזבחו לה' ביום ההוא מן השלל הביאו: בקר שבע מאות, וצאן שבעת אלפים;",
  "15_12": "ויבואו בברית לדרוש את ה' אלוהי אבותיהם בכל לבבם ובכל נפשם;",
  "15_13": "וכל אשר לא ידרוש לה' אלוהי ישראל יומת, למן קטן ועד גדול, למאיש ועד אישה;",
  "15_14": "ויישבעו לה' בקול גדול, ובתרועה, ובחצוצרות ובשופרות;",
  "15_15": "וישמחו כל יהודה על השבועה, כי בכל לבבם נשבעו ובכל רצונם ביקשוהו, ויימצא להם; וינח ה' להם מסביב;",
  "15_16": "וגם את מעכה אם אסא המלך הסירה מגבירה, אשר עשתה מפלצת לאשרה; ויכרות אסא את מפלצתה וידק וישרוף בנחל קדרון;",
  "15_17": "והבמות לא סרו מישראל; אך לבב אסא היה שלם כל ימיו;",
  "15_18": "ויבא את קודשי אביו וקודשיו בית האלוהים: כסף וזהב וכלים;",
  "15_19": "ומלחמה לא הייתה עד שנת שלושים וחמש למלכות אסא.",
  "16_1": "בשנת שלושים ושש למלכות אסא עלה בעשא מלך ישראל על יהודה, ויבן את הרמה לבלתי תת יוצא ובא לאסא מלך יהודה;",
  "16_2": "ויוצא אסא כסף וזהב מאוצרות בית ה' ובית המלך, וישלח אל בן הדד מלך ארם היושב בדמשק לאמור:",
  "16_3": "'ברית ביני ובינך ובין אבי ובין אביך; הנה שלחתי לך כסף וזהב, לך הפרה בריתך את בעשא מלך ישראל ויעלה מעליי!';",
  "16_4": "וישמע בן הדד אל המלך אסא, וישלח את שרי החיילים אשר לו אל ערי ישראל, ויכו את עיון ואת דן ואת אבל מים ואת כל מסכנות ערי נפתלי;",
  "16_5": "ויהי כשמוע בעשא, ויחדל מבנות את הרמה וישבת את מלאכתו;",
  "16_6": "ואסא המלך לקח את כל יהודה, ויישאו את אבני הרמה ואת עציה אשר בנה בעשא, ויבן בהם את גבע ואת המצפה;",
  "16_7": "ובעת ההיא בא חנני הרואה אל אסא מלך יהודה, ויאמר אליו: 'בהישענך על מלך ארם ולא נשענת על ה' אלוהיך – על כן נמלט חיל מלך ארם מידך!;",
  "16_8": "הלא הכושים והלובים היו לחיל לרוב מאוד ברכב ובפרשים להרבה מאוד, ובהישענך על ה' נתנם בידך!;",
  "16_9": "כי ה' עיניו משוטטות בכל הארץ להתחזק עם לבבם שלם אליו; נסכלת על זאת, כי מעתה יש עימך מלחמות!';",
  "16_10": "ויכעס אסא אל הרואה וייתנהו בית המהפכת (בכלא), כי בזעף עימו על זאת; וירצץ אסא מן העם בעת ההיא;",
  "16_11": "והנה דברי אסא הראשונים והאחרונים, הינם כתובים על ספר המלכים ליהודה וישראל;",
  "16_12": "ויחלה אסא בשנת שלושים ותשע למלכותו ברגליו עד למעלה חוליו, וגם בחוליו לא דרש את ה' כי אם ברופאים בלבד;",
  "16_13": "וישכב אסא עם אבותיו, וימת בשנת ארבעים ואחת למלכו;",
  "16_14": "ויקברוהו בקברותיו אשר כרה לו בעיר דוד, וישכיבוהו במיטה אשר מילא בשמים וזנים מרוקחים במרקחת מעשה, וישרפו לו שרפה גדולה עד למאוד.",
  "17_1": "וימלוך יהושפט בנו תחתיו, ויתחזק על ישראל;",
  "17_2": "וייתן חיל בכל ערי יהודה הבצורות, וייתן נציבים בארץ יהודה ובערי אפרים אשר לכד אסא אביו;",
  "17_3": "ויהי ה' עם יהושפט, כי הלך בדרכי דוד אביו הראשונים ולא דרש לבעלים;",
  "17_4": "כי לאלוהי אביו דרש ובמצוותיו הלך, ולא כמעשה ישראל;",
  "17_5": "ויכן ה' את הממלכה בידו, וייתנו כל יהודה מנחה ליהושפט, ויהי לו עושר וכבוד לרוב;",
  "17_6": "ויגבה לבו בדרכי ה', ועוד הסיר את הבמות ואת האשרים מיהודה;",
  "17_7": "ובשנת שלוש למלכו שלח לשריו: לבן חיל ולעובדיה ולזכריה ולנתנאל ולמיכיהו, ללמד בערי יהודה;",
  "17_8": "ועימהם הלוויים: שמעיהו ונתניהו וזבדיהו ועשהאל ושמיkeyרמות ויהונתן ואדוניהו וטוביהו וטוב אדוניה הלוויים, ועימהם אלישמע ויהורם הכוהנים;",
  "17_9": "וילמדו ביהודה ועימהם ספר תורת ה', ויסובו בכל ערי יהודה וילמדו בעם;",
  "17_10": "ויהי פחד ה' על כל ממלכות הארצות אשר סביבות יהודה, ולא נלחמו עם יהושפט;",
  "17_11": "ומן פלשתים מביאים ליהושפט מנחה וכסף משא; גם הערבים מביאים לו צאן: אילים שבעת אלפים ושבע מאות, ותיישים שבעת אלפים ושבע מאות;",
  "17_12": "ויהי יהושפט הולך וגדול עד למעלה, ויבן ביהודה בירניות וערי מסכנות;",
  "17_13": "ומלאכה רבה הייתה לו בערי יהודה, ואנשי מלחמה גיבורי חיל בירושלים;",
  "17_14": "ואלה פקודתם לבית אבותם: ליהודה שרי אלפים – עדנה השר, ועימו גיבורי חיל שלוש מאות אלף;",
  "17_15": "ועל ידו יהוחנן השר, ועימו מאתיים ושמונים אלף;",
  "17_16": "ועל ידו עמסיה בן זכרי המתנדב לה', ועימו מאתיים אלף גיבור חיל;",
  "17_17": "ומן בנימין גיבור חיל אלידע, ועימו נושקי קשת ומגן מאתיים אלף;",
  "17_18": "ועל ידו יהוזבד, ועימו מאה ושמונים אלף חלוצי צבא;",
  "17_19": "אלה המשרתים את המלך, מלבד אשר נתן המלך בערי המבצר בכל יהודה.",
  "18_1": "ויהי ליהושפט עושר וכבוד לרוב, ויתחתן לאחאב מלך ישראל;",
  "18_2": "ויירד לקץ שנים אל אחאב לשומרון; ויזבח לו אחאב צאן ובקר לרוב ולעם אשר עימו, ויסיתהו לעלות אל רמות גלעד;",
  "18_3": "ויאמר אחאב מלך ישראל אל יהושפט מלך יהודה: 'התלך עימי רמות גלעד?'; ויאמר לו: 'כמוני כמוך, וכעמך עמי, ועימך במלחמה!';",
  "18_4": "ויאמר יהושפט אל מלך ישראל: 'דרוש נא כיום את דבר ה'!';",
  "18_5": "וייקבץ מלך ישראל את הנביאים ארבע מאות איש, ויאמר אליהם: 'הנלך אל רמות גלעד למלחמה אם אחדל?'; ויאמרו: 'עלה, וייתן האלוהים ביד המלך!';",
  "18_6": "ויאמר יהושפט: 'האין פה נביא לה' עוד, ונדרשה מאותו?';",
  "18_7": "ויאמר מלך ישראל אל יהושפט: 'עוד איש אחד לדרוש את ה' מאותו, ואני שנאתיו, כי איננו מתנבא עליי לטובה כי אם כל ימיו לרעה – הוא מיכיהו בן ימלא!'; ויאמר יהושפט: 'אל יאמר המלך כן!';",
  "18_8": "ויקרא מלך ישראל אל סריס אחד, ויאמר: 'מהר מיכיהו בן ימלא!';",
  "18_9": "ומלך ישראל ויהושפט מלך יהודה יושבים איש על כיסאו מלובשים בגדים ויושבים בגורן פתח שער שומרון, וכל הנביאים מתנבאים לפניהם;",
  "18_10": "ויעש לו צדקיה בן כנענה קרני ברזל, ויאמר: 'כה אמר ה': באלה תנגח את ארם עד כלותם!';",
  "18_11": "וכל הנביאים מתנבאים כן לאמור: 'עלה רמות גלעד והצלח, ונתן ה' ביד המלך!';",
  "18_12": "והמלאך אשר הלך לקרוא למיכיהו דיבר אליו לאמור: 'הנה דברי הנביאים פה אחד טוב אל המלך; ויהי נא דבריך כאחד מהם ודיברת טוב!';",
  "18_13": "ויאמר מיכיהו: 'חי ה', כי את אשר יאמר אלוהיי אותו אדבר!';",
  "18_14": "ויבוא אל המלך; ויאמר המלך אליו: 'מיכה, הנלך אל רמות גלעד למלחמה אם אחדל?'; ויאמר בלעג: 'עלו והצליחו, ויינתנו בידכם!';",
  "18_15": "ויאמר אליו המלך: 'עד כמה פעמים אני משביעך אשר לא תדבר אליי רק אמת בשם ה'?!';",
  "18_16": "ויאמר: 'ראיתי את כל ישראל נפוצים על ההרים כצאן אשר אין להם רועה; ויאמר ה': \"לא אדונים לאלה, ישובו איש לביתו בשלום!\"';",
  "18_17": "ויאמר מלך ישראל אל יהושפט: 'הלא אמרתי אליך לא יתנבא עליי טוב כי אם לרע?!';",
  "18_18": "ויאמר: 'לכן שמעו דבר ה'! ראיתי את ה' יושב על כיסאו, וכל צבא השמים עומדים על ימינו ועל שמאלו;",
  "18_19": "ויאמר ה': \"מי יפתה את אחאב מלך ישראל ויעל וייפול ברמות גלעד?\"; ויאמר זה אומר ככה וזה אומר ככה;",
  "18_20": "וייצא הרוח ויעמוד לפני ה' ויאמר: \"אני אפתנו!\"; ויאמר לו ה': \"במה?\";",
  "18_21": "ויאמר: \"אצא והייתי רוח שקר בפי כל נביאיו!\"; ויאמר: \"תפתה וגם תוכל; צא ועשה כן!\";",
  "18_22": "ועתה הנה נתן ה' רוח שקר בפי נביאיך אלה, וה' דיבר עליך רעה!';",
  "18_23": "וייגש צדקיה בן כנענה ויך את מיכיהו על הלחי, ויאמר: 'אי זה הדרך עבר רוח ה' מאיתי לדבר אותך?!';",
  "18_24": "ויאמר מיכיהו: 'הנך רואה ביום ההוא אשר תבוא חדר בחדר להחבא!';",
  "18_25": "ויאמר מלך ישראל: 'קחו את מיכיהו והשיבוהו אל אמון שר העיר ואל יואש בן המלך;",
  "18_26": "ואמרתם: כה אמר המלך: שימו זה בית הכלא והאכילוהו לחם לחץ ומים לחץ עד שובי בשלום!';",
  "18_27": "ויאמר מיכיהו: 'אם שוב תשוב בשלום – לא דיבר ה' בי!'; ויאמר: 'שמעו עמים כולם!';",
  "18_28": "ויעל מלך ישראל ויהושפט מלך יהודה אל רמות גלעד;",
  "18_29": "ויאמר מלך ישראל אל יהושפט: 'התחפש ובוא במלחמה, ואתה לבש בגדיך!'; ויתחפש מלך ישראל ויבואו במלחמה;",
  "18_30": "ומלך ארם ציווה את שרי הרכב אשר לו לאמור: 'לא תילחמו את הקטן ואת הגדול, כי אם את מלך ישראל לבדו!';",
  "18_31": "ויהי כראות שרי הרכב את יהושפט, והמה אמרו: 'מלך ישראל הוא!', ויסובו עליו להילחם; ויזעק יהושפט, וה' עזרו ויסיתם אלוהים ממנו;",
  "18_32": "ויהי כראות שרי הרכב כי לא היה מלך ישראל, וישובו מאחריו;",
  "18_33": "ואיש משך בקשת לתומו, ויך את מלך ישראל בין הדבקים ובין השריון; ויאמר לרכבו: 'הפוך ידיך והוציאני מן המחנה, כי החלייתי!';",
  "18_34": "ותעל המלחמה ביום ההוא, ומלך ישראל היה מעמיד במרכבה נוכח ארם עד הערב; וימת לעת בוא השמש.",
  "19_1": "וישב יהושפט מלך יהודה אל ביתו בשלום לירושלים;",
  "19_2": "וייצא אל פניו יהוא בן חנני החוזה, ויאמר אל המלך יהושפט: 'הלרשע לעזור ולשונאי ה' תאהב?! ובזאת עליך קצף מלפני ה'!;",
  "19_3": "אבל דברים טובים נמצאו עימך, כי ביערת האשרות מן הארץ והכינות לבבך לדרוש האלוהים!';",
  "19_4": "ויישב יהושפט בירושלים; וישב וייצא בעם מבאר שבע עד הר אפרים, וישיבם אל ה' אלוהי אבותיהם;",
  "19_5": "ויעמד שופטים בארץ בכל ערי יהודה הבצורות לעיר ועיר;",
  "19_6": "ויאמר אל השופטים: 'ראו מה אתם עושים, כי לא לאדם תשפטו כי לה', ועימכם בדבר משפט!;",
  "19_7": "ועתה יהי פחד ה' עליכם; שמרו ועשו, כי אין עם ה' אלוהינו עוולה ומשוא פנים ומקח שוחד!';",
  "19_8": "וגם בירושלים העמיד יהושפט מן הלוויים והכוהנים ומראשי האבות לישראל למשפט ה' ולריב, וישובו ירושלים;",
  "19_9": "ויצו עליהם לאמור: 'כה תעשון ביראת ה' באמונה ובלבב שלם!;",
  "19_10": "וכל ריב אשר יבוא עליכם מאחיכם היושבים בעריהם, בין דם לדם, בין תורה למצווה, לחוקים ולמשפטים – והזהרתם אותם ולא יאשמו לה' והיה קצף עליכם ועל אחיכם; כה תעשון ולא תאשמו!;",
  "19_11": "והנה אמריהו כוהן הראש עליכם לכל דבר ה', וזבדיהו בן ישמעאל הנגיד לבית יהודה לכל דבר המלך, ושוטרים הלוויים לפניכם; חזקו ועשו, ויהי ה' עם הטוב!'.",
  "20_1": "ויהי אחרי כן באו בני מואב ובני עמון ועימהם מן המעונים על יהושפט למלחמה;",
  "20_2": "ויבואו ויגידו ליהושפט לאמור: 'בא עליך המון רב מעבר לים מארם, והנם בחצצון תמר – היא עין גדי!';",
  "20_3": "ויירא יהושפט, וייתן את פניו לדרוש לה', ויקרא צום על כל יהודה;",
  "20_4": "וייקבצו יהודה לבקש מה'; גם מכל ערי יהודה באו לבקש את ה';",
  "20_5": "ויעמוד יהושפט בקהל יהודה וירושלים בבית ה' לפני החצר החדשה;",
  "20_6": "ויאמר: 'ה' אלוהי אבותינו, הלא אתה הוא אלוהים בשמים ואתה מושל בכל ממלכות הגויים, ובידך כוח וגבורה ואין עמך להתייצב!;",
  "20_7": "הלא אתה אלוהינו הורשת את יושבי הארץ הזאת מלפני עמך ישראל, ותיתנה לזרע אברהם אוהבך לעולם!;",
  "20_8": "ויישבו בה, ויבנו לך בה מקדש לשמך לאמור:;",
  "20_9": "\"אם תבוא עלינו רעה: חרב שפוט ודבר ורעב – נעמדה לפני הבית הזה ולפניך (כי שמך בבית הזה), ונזעק אליך מצרתנו ותשמע ותושיע!\";",
  "20_10": "ועתה הנה בני עמון ומואב והר שעיר, אשר לא נתת לישראל לבוא בהם בבואם מארץ מצרים כי סרו מעליהם ולא השמידום –",
  "20_11": "והנה הם גומלים עלינו לבוא לגרשנו מירושתך אשר הורשתנו!;",
  "20_12": "אלוהינו, הלא תשפוט בם?! כי אין בנו כוח לפני ההמון הגדול הזה הבא עלינו, ואנחנו לא נדע מה נעשה – כי עליך עינינו!';",
  "20_13": "וכל יהודה עומדים לפני ה', גם טפם, נשיהם ובניהם;",
  "20_14": "ויחזיאל בן זכריהו בן בניה בן יעיאל בן מתניה הלוי מן בני אסף, הייתה עליו רוח ה' בתוך הקהל;",
  "20_15": "ויאמר: 'הקשיבו כל יהודה ויושבי ירושלים והמלך יהושפט! כה אמר ה' לכם: אתם אל תיראו ואל תחתו מפני ההמון הגדול הזה, כי לא לכם המלחמה כי לאלוהים!;",
  "20_16": "מחר רדו עליהם; הנם עולים במעלה הציץ, ומצאתם אותם בסוף הנחל לפני מדבר ירואל;",
  "20_17": "לא לכם להילחם בזאת; התייצבו עמדו וראו את ישועת ה' עימכם, יהודה וירושלים! אל תיראו ואל תחתו; מחר צאו לפניהם וה' עימכם!';",
  "20_18": "וייקוד יהושפט אפיים ארצה, וכל יהודה ויושבי ירושלים נפלו לפני ה' להשתחוות לה';",
  "20_19": "ויקומו הלוויים מן בני הקהתים ומן בני הקורחים להלל לה' אלוהי ישראל בקול גדול למעלה;",
  "20_20": "וישכימו בבוקר וייצאו למדבר תקוע; ובצאתם עמד יהושפט ויאמר: 'שמעוני יהודה ויושבי ירושלים! האמינו בה' אלוהיכם ותיאמנו, האמינו בנביאיו והצליחו!';",
  "20_21": "וייוועץ אל העם ויעמד משוררים לה' ומהללים להדרת קודש בצאת לפני החלוץ ואומרים: 'הודו לה' כי לעולם חסדו!';",
  "20_22": "ובעת החלו ברינה ותהילה נתן ה' מארבים על בני עמון מואב והר שעיר הבאים ליהודה, ויינגפו;",
  "20_23": "ויעמדו בני עמון ומואב על יושבי הר שעיר להחרים ולהשמיד; וככלותם ביושבי שעיר עזרו איש ברעהו למשחית;",
  "20_24": "ויהודה בא על המצפה למדבר, ויפנו אל ההמון והנם פגרים נופלים ארצה ואין פליטה;",
  "20_25": "ויבוא יהושפט ועמו לבוז את שללם, וימצאו בהם לרוב ורכוש ופגרים וכלי חמדות, וינצלו להם לאין משא; ויהיו ימים שלושה בוזזים את השלל כי רב הוא;",
  "20_26": "וביום הרביעי נקהלו לעמק ברכה, כי שם ברכו את ה'; על כן קראו את שם המקום ההוא 'עמק ברכה' עד היום הזה;",
  "20_27": "וישובו כל איש יהודה וירושלים ויהושפט בראשם לשוב אל ירושלים בשמחה, כי שימחם ה' מאויביהם;",
  "20_28": "ויבואו ירושלים בנבלים ובכינורות ובחצוצרות אל בית ה';",
  "20_29": "ויהי פחד אלוהים על כל ממלכות הארצות בשומעם כי נלחם ה' עם אויבי ישראל;",
  "20_30": "ותשקוט מלכות יהושפט, וינח לו אלוהיו מסביב;",
  "20_31": "וימלוך יהושפט על יהודה; בן שלושים וחמש שנה במלכו, ועשרים וחמש שנה מלך בירושלים, ושם אמו עזובה בת שילחי;",
  "20_32": "וילך בדרך אביו אסא ולא סר ממנה, לעשות הישר בעיני ה';",
  "20_33": "אך הבמות לא סרו, ועוד העם לא הכינו לבבם לאלוהי אבותיהם;",
  "20_34": "ויתר דברי יהושפט הראשונים והאחרונים, הינם כתובים בדברי יהוא בן חנני אשר הועלה על ספר מלכי ישראל;",
  "20_35": "ואחרי כן אתחבר יהושפט מלך יהודה עם אחזיה מלך ישראל, הוא הרשיע לעשות;",
  "20_36": "ויחברהו עימו לעשות אוניות ללכת תרשיש; ויעשו אוניות בעציון גבר;",
  "20_37": "ויתנבא אליעזר בן דודוהו ממרשה על יהושפט לאמור: 'בהתחברך עם אחזיהו פרץ ה' את מעשיך!'; ויישברו אוניות ולא עצרו כוח ללכת אל תרשיש.",
  "21_1": "וישכב יהושפט עם אבותיו וייקבר עם אבותיו בעיר דוד, וימלוך יהורם בנו תחתיו;",
  "21_2": "ולו אחים בני יהושפט: עזריה, ויחיאל, וזכריהו, ועזריהו, ומיכאל, ושפטיהו; כל אלה בני יהושפט מלך ישראל (יהודה);",
  "21_3": "וייתן להם אביהם מתנות רבות לכסף ולזהב ולמגדנות עם ערי מצורות ביהודה; ואת הממלכה נתן ליהורם כי הוא הבכור;",
  "21_4": "ויקם יהורם על ממלכת אביו ויתחזק, ויהרוג את כל אחיו בחרב, וגם משרי ישראל;",
  "21_5": "בן שלושים ושתיים שנה יהורם במלכו, ושמונה שנים מלך בירושלים;",
  "21_6": "וילך בדרך מלכי ישראל כאשר עשו בית אחאב, כי בת אחאב (עתליה) הייתה לו לאישה; ויעש הרע בעיני ה';",
  "21_7": "ולא אבה ה' להשחית את בית דוד למען הברית אשר כרת לדוד, וכאשר אמר לתת לו ניר ולבניו כל הימים;",
  "21_8": "בימיו פשע אדום מתחת יד יהודה, וימליכו עליהם מלך;",
  "21_9": "ויעבור יהורם עם שריו וכל הרכב עימו; ויהי קם לילה ויך את אדום הסובב אליו ואת שרי הרכב;",
  "21_10": "ויפשע אדום מתחת יד יהודה עד היום הזה; אז פשעה לבנה בעת ההיא מתחת ידו, כי עזב את ה' אלוהי אבותיו;",
  "21_11": "גם הוא עשה במות בהרי יהודה, ויזן את יושבי ירושלים וידח את יהודה;",
  "21_12": "ויבוא אליו מכתב מאליהו הנביא לאמור: 'כה אמר ה' אלוהי דוד אביך: יען אשר לא הלכת בדרכי יהושפט אביך ובדרכי אסא מלך יהודה;",
  "21_13": "ותלך בדרך מלכי ישראל ותזנה את יהודה ואת יושבי ירושלים כהזנות בית אחאב, וגם את אחיך בית אביך הטובים ממך הרגת –",
  "21_14": "הנה ה' נוגף מגפה גדולה בעמך, ובבניך, ובנשיך ובכל רכושך;",
  "21_15": "ואתה בחליים רבים במחלת מעיך, עד שייצאו מעיך מן החולי ימים על ימים!';",
  "21_16": "ויעורר ה' על יהורם את רוח הפלשתים והערבים אשר על יד כושים;",
  "21_17": "ויעלו ביהודה ויבקעוה, וישבו את כל הרכוש הנמצא לבית המלך וגם בניו ונשיו, ולא נשאר לו בן כי אם יהואחז (אחזיהו) קטון בניו;",
  "21_18": "ואחרי כל זאת נגפו ה' במעיו לחולי לאין מרפא;",
  "21_19": "ויהי לימים מימים וכעת צאת הקץ לימים שניים יצאו מעיו עם חוליו וימת בתחלואים רעים; ולא עשו לו עמו שרפה כשרפת אבותיו;",
  "21_20": "בן שלושים ושתיים היה במלכו ושמונה שנים מלך בירושלים, וילך בלא חמדה (בלא שאיש הצטער עליו); ויקברוהו בעיר דוד, ולא בקברות המלכים.",
  "22_1": "וימליכו יושבי ירושלים את אחזיהו בנו הקטון תחתיו, כי כל הראשונים הרג הגדוד הבא בערבים למחנה; וימלוך אחזיהו בן יהורם מלך יהודה;",
  "22_2": "בן ארבעים ושתיים שנה אחזיהו במלכו, ושנה אחת מלך בירושלים, ושם אמו עתליהו בת (נכדת) עמרי;",
  "22_3": "גם הוא הלך בדרכי בית אחאב, כי אמו הייתה יועצתו להרשיע;",
  "22_4": "ויעש הרע בעיני ה' כבית אחאב, כי המה היו לו יועצים אחרי מות אביו למשחית לו;",
  "22_5": "גם בעצתם הלך, וילך את יהורם בן אחאב מלך ישראל למלחמה על חזאל מלך ארם ברמות גלעד; ויכו הארמים את יורם;",
  "22_6": "וישב להתרפא ביזרעאל כי המכות אשר היכוהו ברמה בהילחמו את חזאל מלך ארם; ועזריהו בן יהורם מלך יהודה ירד לראות את יורם בן אחאב ביזרעאל כי חולה הוא;",
  "22_7": "ומאלוהים הייתה תבוסת אחזיהו לבוא אל יורם; ובבואו יצא עם יהורם אל יהוא בן נמשי אשר משחו ה' להכרית את בית אחאב;",
  "22_8": "ויהי כהישפט יהוא עם בית אחאב, וימצא את שרי יהודה ובני אחי אחזיהו משרתים לאחזיהו, ויהרגם;",
  "22_9": "ויבקש את אחזיהו וילכדוהו והוא מתחבא בשומרון, ויביאוהו אל יהוא וימיתוהו ויקברוהו, כי אמרו: 'בן יהושפט הוא אשר דרש את ה' בכל לבבו!'; ואין לבית אחזיהו לעצור כוח לממלכה;",
  "22_10": "ועתליהו אם אחזיהו ראתה כי מת בנה, ותקם ותדבר את כל זרע הממלכה לבית יהודה;",
  "22_11": "ותיקח יהושבעת בת המלך את יואש בן אחזיהו ותגנוב אותו מתוך בני המלך המומתים, ותיתן אותו ואת מינקתו בחדר המיטות; ותסתירהו יהושבעת בת המלך יהורם אשת יהוידע הכוהן (כי אחות אחזיהו הייתה) מפני עתליהו, ולא המיתתו;",
  "22_12": "ויהי עימם בבית האלוהים מתחבא שש שנים; ועתליה מולכת על הארץ.",
  "23_1": "ובשנה השביעית התחזק יהוידע, וייקח את שרי המאות: לעזריה בן ירוחם, ולישמעאל בן יהוחנן, ולעזריהו בן עובד, ולמעשיהו בן עדיהו, ולאלישפט בן זכרי עימו בברית;",
  "23_2": "ויסובו ביהודה וייקבצו את הלוויים מכל ערי יהודה וראשי האבות לישראל, ויבואו אל ירושלים;",
  "23_3": "ויכרות כל הקהל ברית בבית האלוהים עם המלך; ויאמר להם: 'הנה בן המלך ימלוך כאשר דיבר ה' על בני דוד!;",
  "23_4": "זה הדבר אשר תעשו: השלישית מכם באי השבת, לכוהנים וללוויים, לשוערי הסיפים;",
  "23_5": "והשלישית בבית המלך, והשלישית בשער היסוד; וכל העם בחצרות בית ה';",
  "23_6": "ואל יבוא בית ה' כי אם הכוהנים והמשרתים ללוויים המה יבואו כי קודש המה; וכל העם ישמרו משמרת ה';",
  "23_7": "והקיפו הלוויים את המלך סביב איש וכליו בידו, והבא אל הבית יומת; והיו את המלך בבואו ובצאתו!';",
  "23_8": "ויעשו הלוויים וכל יהודה ככל אשר ציווה יהוידע הכוהן, וייקחו איש את אנשיו באי השבת עם יוצאי השבת, כי לא פטר יהוידע הכוהן את המחלקות;",
  "23_9": "וייתן יהוידע הכוהן לשרי המאות את החניתות ואת המגנים ואת השלטים אשר למלך דוד אשר בבית האלוהים;",
  "23_10": "ויעמד את כל העם ואיש שלחו בידו מכתף הבית הימנית עד כתף הבית השמאלית למזבח ולבית, על המלך סביב;",
  "23_11": "ויוציאו את בן המלך וייתנו עליו את הנזר ואת העדות, וימליכו אותו; וימשחוהו יהוידע ובניו, ויאמרו: 'יחי המלך!';",
  "23_12": "ותשמע עתליהו את קול העם הרצים והמהללים את המלך, ותבוא אל העם בית ה';",
  "23_13": "ותרא והנה המלך עומד על עמודו במבוא והשרים והחצוצרות על המלך וכל עם הארץ שמח ותוקע בחצוצרות והמשוררים בכלי השיר ומודיעים להלל; ותקרע עתליהו את בגדיה ותאמר: 'קשר, קשר!';",
  "23_14": "ויוצא יהוידע הכוהן את שרי המאות פקודי החיל ויאמר אליהם: 'הוציאוה אל מחוץ לשדרות, והבא אחריה יומת בחרב!', כי אמר הכוהן: 'לא תמיתוה בבית ה'!';",
  "23_15": "וישימו לה ידיים, ותבוא אל מבוא שער הסוסים בית המלך, וימיתוה שם;",
  "23_16": "ויכרות יהוידע ברית בינו ובין כל העם ובין המלך, להיות לעם לה';",
  "23_17": "ויבואו כל העם בית הבעל וייתצוהו ואת מזבחותיו, ואת צלמיו שיברו, ואת מתן כוהן הבעל הרגו לפני המזבחות;",
  "23_18": "וישם יהוידע פקודות בית ה' ביד הכוהנים הלוויים אשר חלק דוד על בית ה' להעלות עולות ה' ככתוב בתורת משה, בשמחה ובשיר על ידי דוד;",
  "23_19": "ויעמד השוערים על שערי בית ה', ולא יבוא טמא לכל דבר;",
  "23_20": "וייקח את שרי המאות ואת האדירים ואת המושלים בעם ואת כל עם הארץ, ויורד את המלך מבית ה' ויבואו בתוך שער העליון בית המלך, ויושיבו את המלך על כיסא הממלכה;",
  "23_21": "וישמחו כל עם הארץ והעיר שקטה; ואת עתליהו המיתו בחרב.",
  "24_1": "בן שבע שנים יואש במלכו, וארבעים שנה מלך בירושלים, ושם אמו צביה מבאר שבע;",
  "24_2": "ויעש יואש הישר בעיני ה' כל ימי יהוידע הכוהן;",
  "24_3": "ויישא לו יהוידע נשים שתיים, ויולד בנים ובנות;",
  "24_4": "ויהי אחרי כן היה עם לב יואש לחדש את בית ה';",
  "24_5": "וייקבץ את הכוהנים והלוויים ויאמר להם: 'צאו לערי יהודה וקבצו מכל ישראל כסף לחזק את בית אלוהיכם מדי שנה בשנה, ואתם תמהרו לדבר!'; ולא מיהרו הלוויים;",
  "24_6": "ויקרא המלך ליהוידע הראש ויאמר לו: 'מדוע לא דרשת על הלוויים להביא מיהודה ומירושלים את משאת משה עבד ה' והקהל לישראל לאוהל העדות?!';",
  "24_7": "כי עתליהו המרשעת ובניה פרצו את בית האלוהים, וגם כל קודשי בית ה' עשו לבעלים;",
  "24_8": "ויאמר המלך ויעשו ארון אחד, וייתנוהו בשער בית ה' חוצה;",
  "24_9": "וייתנו קול ביהודה ובירושלים להביא לה' משאת משה עבד האלוהים על ישראל במדבר;",
  "24_10": "וישמחו כל השרים וכל העם, ויביאו וישליכו לארון עד לכלה;",
  "24_11": "ויהי בעת יביא את הארון אל פקודת המלך ביד הלוויים וכראותם כי רב הכסף, ובא סופר המלך ופקיד כוהן הראש ויערו את הארון ויישאוהו וישיבוהו אל מקומו; כה עשו ליום ביום ויאספו כסף לרוב;",
  "24_12": "וייתנהו המלך ויהוידע אל עושה מלאכת עבודת בית ה', ויהיו שוכרים חוצבים וחרשים לחדש בית ה', וגם לחרשי ברזל ונחושת לחזק את בית ה';",
  "24_13": "ויעשו עושי המלאכה ותעל ארוכה למלאכה בידם, ויעמידו את בית האלוהים על מתכונתו ויאמצוהו;",
  "24_14": "וככלותם הביאו לפני המלך ויהוידע את שאר הכסף ויעשהו כלים לבית ה' כלי שרת ולהעלות וכפות וכלי זהב וכסף; ויהיו מעלים עולות בבית ה' תמיד כל ימי יהוידע;",
  "24_15": "ויזקן יהוידע וישבע ימים וימת; בן מאה ושלושים שנה במותו;",
  "24_16": "ויקברוהו בעיר דוד עם המלכים, כי עשה טובה בישראל ועם האלוהים וביתו;",
  "24_17": "ואחרי מות יהוידע באו שרי יהודה וישתחוו למלך; אז שמע המלך אליהם;",
  "24_18": "ויעזבו את בית ה' אלוהי אבותיהם ויעבדו את האשרים ואת העצבים; ויהי קצף על יהודה וירושלים באשמתם זאת;",
  "24_19": "וישלח בהם נביאים להשיבם אל ה', ויעידו בם ולא האזינו;",
  "24_20": "ורוח אלוהים לבשה את זכריה בן יהוידע הכוהן ויעמוד מעל לעם, ויאמר להם: 'כה אמר האלוהים: למה אתם עוברים את מצוות ה' ולא תצליחו?! כי עזבתם את ה' – ויעזוב אתכם!';",
  "24_21": "וייקשרו עליו וירגמוהו אבן במצוות המלך בחצר בית ה';",
  "24_22": "ולא זכר יואש המלך החסד אשר עשה יהוידע אביו עימו ויהרוג את בנו; וכמותו אמר: 'ירא ה' וידרוש!';",
  "24_23": "ויהי לתקופת השנה עלה עליו חיל ארם ויבואו אל יהודה וירושלים, וישחיתו את כל שרי העם מן העם, וכל שללם שילחו למלך דמשק;",
  "24_24": "כי במצער אנשים באו חיל ארם, וה' נתן בידם חיל לרוב מאוד כי עזבו את ה' אלוהי אבותיהם; ואת יואש עשו שפטים;",
  "24_25": "ובלכתם ממנו – כי עזבו אותו במחליים רבים – התקשרו עליו עבדיו בדמי בני יהוידע הכוהן ויהרגוהו על מיטתו וימת; ויקברוהו בעיר דוד, ולא קברוהו בקברות המלכים;",
  "24_26": "ואלה המתקשרים עליו: זבד בן שמעת העמונית, ויהוזבד בן שמרית המואבית;",
  "24_27": "ובניו ורב המשא עליו ויסוד בית האלוהים, הינם כתובים על מדרש ספר המלכים; וימלוך אמציהו בנו תחתיו.",
  "25_1": "בן עשרים וחמש שנה מלך אמציהו, ועשרים ותשע שנה מלך בירושלים, ושם אמו יהועדן מירושלים;",
  "25_2": "ויעש הישר בעיני ה', רק לא בלבב שלם;",
  "25_3": "ויהי כאשר חזקה הממלכה עליו, ויהרוג את עבדיו המכים את המלך אביו;",
  "25_4": "ואת בניהם לא המית, כי ככתוב בתורה בספר משה אשר ציווה ה' לאמור: 'לא ימותו אבות על בנים ובנים לא ימותו על אבות, כי אם איש בחטאו ימות!';",
  "25_5": "וייקבץ אמציהו את יהודה ויעמידם לבית אבות לשרי האלפים ולשרי המאות לכל יהודה ובנימין, ויפקדם מבן עשרים שנה ומעלה, וימצאם שלוש מאות אלף בחור יוצא צבא נושא רומח וצנה;",
  "25_6": "וישכור מישראל מאה אלף גיבור חיל במאה כיכר כסף;",
  "25_7": "ואיש האלוהים בא אליו לאמור: 'המלך, אל יבוא עימך צבא ישראל, כי אין ה' עם ישראל – כל בני אפרים!;",
  "25_8": "כי אם בוא אתה עשה חזק למלחמה, יכשילך האלוהים לפני אויב, כי יש כוח באלוהים לעזור ולהכשיל!';",
  "25_9": "ויאמר אמציהו לאיש האלוהים: 'ומה לעשות למאת הכיכר אשר נתתי לגדוד ישראל?'; ויאמר איש האלוהים: 'יש לה' לתת לך הרבה מזה!';",
  "25_10": "ויבדילם אמציהו להגדוד אשר בא אליו מאפרים ללכת למקומם; וייחר אפם מאוד ביהודה, וישובו למקומם בחרי אף;",
  "25_11": "ואמציהו התחזק ויינהג את עמו, וילך גיא המלח ויך את בני שעיר עשרת אלפים;",
  "25_12": "ועשרת אלפים חיים שבו בני יהודה, ויביאום לראש הסלע וישליכום מראש הסלע וכולם נבקעו;",
  "25_13": "ובני הגדוד אשר השיב אמציהו מלכת עימו למלחמה, ויפשטו בערי יהודה משומרון ועד בית חורון ויכו מהם שלושת אלפים ויבוזו ביזה רבה;",
  "25_14": "ויהי אחרי בוא אמציהו מהכות את האדומים, ויבא את אלוהי בני שעיר ויעמידם לו לאלוהים, ולפניהם ישתחווה ולהם יקטיר;",
  "25_15": "וייחר אף ה' באמציהו, וישלח אליו נביא ויאמר לו: 'למה דרשת את אלוהי העם אשר לא הצילו את עמם מידך?!';",
  "25_16": "ויהי בדברו אליו ויאמר לו המלך: 'הליועץ למלך נתנוך?! חדל לך, למה יכוך?!'; ויחדל הנביא ויאמר: 'ידעתי כי יעץ אלוהים להשחיתך, כי עשית זאת ולא שמעת לעצתי!';",
  "25_17": "וייוועץ אמציהו מלך יהודה, וישלח אל יואש בן יהואחז בן יהוא מלך ישראל לאמור: 'לכה נתראה פנים למלחמה!';",
  "25_18": "וישלח יואש מלך ישראל אל אמציהו מלך יהודה לאמור: 'החוח אשר בלבנון שלח אל הארז אשר בלבנון לאמור: \"תנה את בתך לבני לאישה\"; ותעבור חית השדה אשר בלבנון ותרמוס את החוח!;",
  "25_19": "אמרת: הנה הכית את אדום, ונשאך לבך להיכבד; עתה שבה בביתך, למה תתגרה ברעה ונפלת אתה ויהודה עימך?!';",
  "25_20": "ולא שמע אמציהו, כי מאת האלוהים הייתה למען תיתם ביד כי דרשו את אלוהי אדום;",
  "25_21": "ויעל יואש מלך ישראל, ויתראו פנים הוא ואמציהו מלך יהודה בבית שמש אשר ליהודה;",
  "25_22": "ויינגף יהודה לפני ישראל, וינוסו איש לאוהליו;",
  "25_23": "ואת אמציהו מלך יהודה בן יואש בן יהואחז תפש יואש מלך ישראל בבית שמש, ויביאהו ירושלים ויפרוץ בחומת ירושלים משער אפרים עד שער הפונה ארבע מאות אמה;",
  "25_24": "וכל הזהב והכסף ואת כל הכלים הנמצאים בבית האלוהים עם עובד אדום ואת אוצרות בית המלך ואת בני התערובות, וישב שומרון;",
  "25_25": "ויחי אמציהו בן יואש מלך יהודה אחרי מות יואש בן יהואחז מלך ישראל חמש עשרה שנה;",
  "25_26": "ויתר דברי אמציהו הראשונים והאחרונים, הלא הינם כתובים על ספר מלכי יהודה וישראל;",
  "25_27": "ומעת אשר סר אמציהו מאחרי ה', ויקשרו עליו קשר בירושלים וינס לכישה; וישלחו אחריו לכישה וימיתוהו שם;",
  "25_28": "ויישאוהו על הסוסים, ויקברו אותו עם אבותיו בעיר יהודה.",
  "26_1": "וייקחו כל עם יהודה את עוזיהו והוא בן שש עשרה שנה, וימליכו אותו תחת אביו אמציהו;",
  "26_2": "הוא בנה את אילות וישיבה ליהודה אחרי שכב המלך עם אבותיו;",
  "26_3": "בן שש עשרה שנה עוזיהו במלכו, וחמישים ושתיים שנה מלך בירושלים, ושם אמו יכיליה מן ירושלים;",
  "26_4": "ויעש הישר בעיני ה' ככל אשר עשה אמציהו אביו;",
  "26_5": "ויהי לדרוש אלוהים בימי זכריהו המבין בראות האלוהים; ובימי דורשו את ה' הצליחו האלוהים;",
  "26_6": "וייצא וילחם בפלשתים, ויפרוץ את חומת גת ואת חומת יבנה ואת חומת אשדוד, ויבן ערים באשדוד ובפלשתים;",
  "26_7": "ויעזרהו האלוהים על פלשתים ועל הערביים היושבים בגור בעל והמעונים;",
  "26_8": "וייתנו העמונים מנחה לעוזיהו, וילך שמו עד לבוא מצרים כי החזיק עד למעלה;",
  "26_9": "ויבן עוזיהו מגדלים בירושלים על שער הפינה ועל שער הגיא ועל המקצוע, ויחזקם;",
  "26_10": "ויבן מגדלים במדבר ויחצוב בורות רבים כי מקנה רב היה לו ובשפלה ובמישור, איכרים וכורמים בהרים ובכרמל כי אוהב אדמה היה;",
  "26_11": "ויהי לעוזיהו חיל עושה מלחמה יוצאי צבא לגדוד במספר פקודתם ביד יעואל הסופר ומעשיהו השוטר, על יד חנניהו משרי המלך;",
  "26_12": "כל מספר ראשי האבות לגיבורי חיל – אלפיים ושש מאות;",
  "26_13": "ועל ידם חיל צבא שלוש מאות אלף ושבעת אלפים וחמש מאות עושי מלחמה בכוח חיל, לעזור למלך על האויב;",
  "26_14": "ויכן להם עוזיהו לכל הצבא מגנים ורמחים וכובעים ושריונות וקשתות ולאבני קלעים;",
  "26_15": "ויעש בירושלים חשבונות מעשה חושב להיות על המגדלים ועל הפינות לירות בחצים ובאבנים גדולות; וייצא שמו למרחוק, כי הפליא להיעזר עד כי חזק;",
  "26_16": "וכחזקתו גבה לבו עד להשחית, וימעל בה' אלוהיו; ויבוא אל היכל ה' להקטיר על מזבח הקטורת;",
  "26_17": "ויבוא אחריו עזריהו הכוהן, ועימו כוהני ה' שמונים בני חיל;",
  "26_18": "ויעמדו על עוזיהו המלך ויאמרו לו: 'לא לך עוזיהו להקטיר לה', כי לכוהנים בני אהרון המקודשים להקטיר! צא מן המקדש כי מעלת, ולא לך לכבוד מה' אלוהים!';",
  "26_19": "וייזעף עוזיהו ובידו מקטרת להקטיר; ובזעפו עם הכוהנים והצרעת זרחה במצחו לפני הכוהנים בבית ה' מעל למזבח הקטורת;",
  "26_20": "ויפן אליו עזריהו כוהן הראש וכל הכוהנים והנה הוא מצורע במצחו, ויבהילוהו משם; וגם הוא נדחף לצאת כי נגעו ה';",
  "26_21": "ויהי עוזיהו המלך מצורע עד יום מותו, ויישב בית החופשית מצורע כי נגזר מבית ה'; ויותם בנו על בית המלך שופט את עם הארץ;",
  "26_22": "ויתר דברי עוזיהו הראשונים והאחרונים כתב ישעיהו בן אמוץ הנביא;",
  "26_23": "וישכב עוזיהו עם אבותיו ויקברו אותו עם אבותיו בשדה הקבורה אשר למלכים כי אמרו: 'מצורע הוא!'; וימלוך יותם בנו תחתיו.",
  "27_1": "בן עשרים וחמש שנה מלך יותם, ושש עשרה שנה מלך בירושלים, ושם אמו ירושה בת צדוק;",
  "27_2": "ויעש הישר בעיני ה' ככל אשר עשה עוזיהו אביו, רק לא בא אל היכל ה' (לא חטא בגאווה כמותו); ועוד העם משחיתים;",
  "27_3": "הוא בנה את שער בית ה' העליון, ובחומת העופל בנה לרוב;",
  "27_4": "וערים בנה בהר יהודה, ובחרשים בנה בירניות ומגדלים;",
  "27_5": "והוא נלחם עם מלך בני עמון ויחזק עליהם, וייתנו לו בני עמון בשנה ההיא מאה כיכר כסף ועשרת אלפים כורים חיטים ושעורים עשרת אלפים; זאת השיבו לו בני עמון בשנה השנייה והשלישית;",
  "27_6": "ויתחזק יותם, כי הכין דרכיו לפני ה' אלוהיו;",
  "27_7": "ויתר דברי יותם וכל מלחמותיו ודרכיו, הינם כתובים על ספר מלכי ישראל ויהודה;",
  "27_8": "בן עשרים וחמש שנה היה במלכו, ושש עשרה שנה מלך בירושלים;",
  "27_9": "וישכב יותם עם אבותיו ויקברו אותו בעיר דוד; וימלוך אחז בנו תחתיו.",
  "28_1": "בן עשרים שנה אחז במלכו, ושש עשרה שנה מלך בירושלים; ולא עשה הישר בעיני ה' כדוד אביו;",
  "28_2": "וילך בדרכי מלכי ישראל, וגם מסכות עשה לבעלים;",
  "28_3": "והוא הקטיר בגיא בן הינום, ויבער את בניו באש כתועבות הגויים אשר הוריש ה' מפני בני ישראל;",
  "28_4": "ויזבח ויקטר בבמות ועל הגבעות ותחת כל עץ רענן;",
  "28_5": "וייתנהו ה' אלוהיו ביד מלך ארם, ויכו בו וישבו ממנו שביה גדולה ויביאו דמשק; וגם ביד מלך ישראל ניתן, ויך בו מכה גדולה;",
  "28_6": "ויהרוג פקח בן רמליהו ביהודה מאה ועשרים אלף ביום אחד – הכול בני חיל – בעוזבם את ה' אלוהי אבותיהם;",
  "28_7": "ויהרוג זכרי גיבור אפרים את מעשיהו בן המלך, ואת עזריקם נגיד הבית, ואת אלקנה משנה המלך;",
  "28_8": "וישבו בני ישראל מאחיהם מאתיים אלף נשים, בנים ובנות, וגם שלל רב בזזו מהם ויביאו את השלל לשומרון;",
  "28_9": "ושם היה נביא לה' עודד שמו, וייצא לפני הצבא הבא לשומרון ויאמר להם: 'הנה בחמת ה' אלוהי אבותיכם על יהודה נתנם בידכם, ותהרגו בם בזעף עד לשמים הגיע!;",
  "28_10": "ועתה בני יהודה וירושלים אתם אומרים לכבוש לעבדים ולשפחות לכם! הלא רק אתם עימכם אשמות לה' אלוהיכם?!;",
  "28_11": "ועתה שמעוני והשיבו השביה אשר שביתם מאחיכם, כי חרון אף ה' עליכם!';",
  "28_12": "ויקומו אנשים מראשי בני אפרים: עזריהו בן יהוחנן, ברכיהו בן משלמות, ויחיזקיהו בן שלום, ועמשא בן חדלי על הבאים מן הצבא;",
  "28_13": "ויאמרו להם: 'לא תביאו את השביה הנה, כי לאשמת ה' עלינו אתם אומרים להוסיף על חטאתינו ועל אשמתנו?! כי רבה אשמה לנו וחרון אף על ישראל!';",
  "28_14": "ויעזוב החלוץ את השביה ואת הביזה לפני השרים וכל הקהל;",
  "28_15": "ויקומו האנשים אשר ניקבו בשמות ויחזיקו בשביה, וכל מערומיהם הלבישו מן השלל, וילבישום וינעילום ויאכילום וישקום ויסוכום וינהלום בחמורים לכל כושל, ויביאום יריחו עיר התמרים אצל אחיהם; וישובו שומרון;",
  "28_16": "בעת ההיא שלח המלך אחז על מלכי אשור לעזור לו;",
  "28_17": "ועוד אדומים באו ויכו ביהודה וישבו שבי;",
  "28_18": "ופלשתים פשטו בערי השפלה והנגב ליהודה, וילכדו את בית שמש ואת איילון ואת הגדרות ואת שוכו ובנותיה ואת תמנה ובנותיה ואת גימזו ואת בנותיה, ויישבו שם;",
  "28_19": "כי הכניע ה' את יהודה בעבור אחז מלך ישראל (יהודה), כי הפריע ביהודה ומעול מעל בה';",
  "28_20": "ויבוא עליו תלגת פלנאסר מלך אשור, ויצר לו ולא חזקו;",
  "28_21": "כי חלק אחז את בית ה' ואת בית המלך והשרים וייתן למלך אשור, ולא לעזרה לו;",
  "28_22": "ובעת הצר לו ויוסף למעול בה' – הוא המלך אחז;",
  "28_23": "ויזבח לאלוהי דמשק המכים בו, ויאמר: 'כי אלוהי מלכי ארם הם עוזרים אותם, להם אזבח ויעזרוני!'; והם היו לו להכשילו ולכל ישראל;",
  "28_24": "וייאסוף אחז את כלי בית האלוהים ויקצץ את כלי בית האלוהים, ויסגור את דלתות בית ה', ויעש לו מזבחות בכל פינה בירושלים;",
  "28_25": "ובכל עיר ועיר ליהודה עשה במות לקטר לאלוהים אחרים, ויכעס את ה' אלוהי אבותיו;",
  "28_26": "ויתר דבריו וכל דרכיו הראשונים והאחרונים, הינם כתובים על ספר מלכי יהודה וישראל;",
  "28_27": "וישכב אחז עם אבותיו ויקברוהו בעיר בירושלים כי לא הביאוהו לקברי מלכי ישראל; וימלוך יחזקיהו בנו תחתיו.",
  "29_1": "יחזקיהו מלך בהיותו בן עשרים וחמש שנה, ועשרים ותשע שנה מלך בירושלים, ושם אמו אביה בת זכריהו;",
  "29_2": "ויעש הישר בעיני ה' ככל אשר עשה דוד אביו;",
  "29_3": "הוא בשנה הראשונה למלכו בחודש הראשון פתח את דלתות בית ה' ויחזקם;",
  "29_4": "ויבא את הכוהנים ואת הלוויים ויאספם לרחוב המזרח;",
  "29_5": "ויאמר להם: 'שמעוני הלוויים! עתה התקדשו וקדשו את בית ה' אלוהי אבותיכם, והוציאו את הנידה מן הקודש!;",
  "29_6": "כי מעלו אבותינו ועשו הרע בעיני ה' אלוהינו ויעזבוהו, ויסבו פניהם ממשכן ה' וייתנו עורף!;",
  "29_7": "גם סגרו דלתות האולם ויכבו את הנרות, וקטורת לא הקטירו ועולה לא העלו בקודש לאלוהי ישראל;",
  "29_8": "ויהי קצף ה' על יהודה וירושלים, וייתנם לזעווה לשמה ולשרקה כאשר אתם רואים בעיניכם!;",
  "29_9": "והנה נפלו אבותינו בחרב, ובנינו ובנותינו ונשינו בשבי על זאת;",
  "29_10": "עתה עם לבבי לכרות ברית לה' אלוהי ישראל, וישוב ממנו חרון אפו!;",
  "29_11": "בניי, עתה אל תשלו, כי בכם בחר ה' לעמוד לפניו לשרתו ולהיות לו משרתים ומקטרים!';",
  "29_12": "ויקומו הלוויים: מחת בן עמשי וקש בן עבדי מן בני הקהתי; ומן בני מררי: קיש בן עבדי ועזריהו בן יהללאל; ומן הגרשוני: יואח בן זימה ועEden בן יואח;",
  "29_13": "ומן בני אליצפן: שמרי ויעואל; ומן בני אסף: זכריהו ומתניהו;",
  "29_14": "ומן בני הימן: יחיאל ושמעי; ומן בני ידותון: שמעיה ועוזיאל;",
  "29_15": "וייאספו את אחיהם ויתקדשו ויבואו כמצוות המלך בדברי ה' לטהר בית ה';",
  "29_16": "ויבואו הכוהנים לפנימה בית ה' לטהר, ויוציאו את כל הטומאה אשר מצאו בהיכל ה' לחצר בית ה'; ויקבלו הלוויים להוציא לנחל קדרון חוצה;",
  "29_17": "ויחלו באחד לחודש הראשון לקדש, וביום שמונה לחודש באו לאולם ה' ויקדשו את בית ה' לימים שמונה, וביום שישה עשר לחודש הראשון כילו;",
  "29_18": "ויבואו פנימה אל יחזקיהו המלך ויאמרו: 'טיהרנו את כל בית ה', ואת מזבח העולה ואת כל כליו, ואת שולחן המערכת ואת כל כליו;",
  "29_19": "ואת כל הכלים אשר הזניח המלך אחז במלכותו במעלו הכנו וקידשנו, והנם לפני מזבח ה'!';",
  "29_20": "וישכם יחזקיהו המלך וייאסוף את שרי העיר, ויעל בית ה';",
  "29_21": "ויביאו פרים שבעה ואילים שבעה וכבשים שבעה וצפירי עיזים שבעה לחטאת על הממלכה ועל המקדש ועל יהודה; ויאמר לבני אהרון הכוהנים להעלות על מזבח ה';",
  "29_22": "וישחטו הבקר ויקבלו הכוהנים את הדם ויזרקו המזבחה, וישחטו האילים ויזרקו הדם המזבחה, וישחטו הכבשים ויזרקו הדם המזבחה;",
  "29_23": "ויגישו את שעירי החטאת לפני המלך והקהל, ויסמכו ידיהם עליהם;",
  "29_24": "וישחטום הכוהנים ויחטאו את דמם המזבחה לכפר על כל ישראל, כי לכל ישראל אמר המלך העולה והחטאת;",
  "29_25": "ויעמד את הלוויים בית ה' במצלתיים בנבלים ובכינורות כמצוות דוד וגד חוזה המלך ונתן הנביא, כי ביד ה' המצווה ביד נביאיו;",
  "29_26": "ויעמדו הלוויים בכלי דוד והכוהנים בחצוצרות;",
  "29_27": "ויאמר יחזקיהו להעלות העולה להמזבח; ובעת החל העולה החל שיר ה' והחצוצרות ועל ידי כלי דוד מלך ישראל;",
  "29_28": "וכל הקהל משתחווים והשיר משורר והחצוצרות מחצצרות, הכול עד לכלות העולה;",
  "29_29": "וככלות להעלות כרעו המלך וכל הנמצאים עימו וישתחוו;",
  "29_30": "ויאמר יחזקיהו המלך והשרים ללוויים להלל לה' בדברי דוד ואסף החוזה; ויהללו עד לשמחה ויקדו וישתחוו;",
  "29_31": "ויען יחזקיהו ויאמר: 'עתה מילאתם ידכם לה'! גשו והביאו זבחים ותודות לבית ה'!'; ויביאו הקהל זבחים ותודות, וכל נדיב לב – עולות;",
  "29_32": "ויהי מספר העולה אשר הביאו הקהל: בקר שבעים, אילים מאה, כבשים מאתיים; לעולה לה' כל אלה;",
  "29_33": "והקודשים: בקר שש מאות, וצאן שלושת אלפים;",
  "29_34": "רק הכוהנים היו למעט ולא יכלו להפשיט את כל העולות, ויחזקום אחיהם הלוויים עד כלות המלאכה ועד יתקדשו הכוהנים, כי הלוויים ישרי לבב להתקדש יותר מן הכוהנים;",
  "29_35": "וגם עולה לרוב בחלבי השלמים ובנסכים לעולה; ותיכון עבודת בית ה';",
  "29_36": "וישמח יחזקיהו וכל העם על ההכין האלוהים לעם, כי פתאום ובהתעוררות עצומה נהיה הדבר.",
  "30_1": "וישלח יחזקיהו על כל ישראל ויהודה וגם איגרות כתב על אפרים ומנשה, לבוא לבית ה' בירושלים לעשות פסח לה' אלוהי ישראל;",
  "30_2": "וייוועץ המלך ושריו וכל הקהל בירושלים לעשות הפסח בחודש השני (אייר, פסח שני);",
  "30_3": "כי לא יכלו לעשותו בעתו (בניסן), כי הכוהנים לא התקדשו למדי והעם לא נאספו לירושלים;",
  "30_4": "ויישר הדבר בעיני המלך ובעיני כל הקהל;",
  "30_5": "ויעמידו דבר להעביר קול בכל ישראל מבאר שבע ועד דן לבוא לעשות פסח לה' אלוהי ישראל בירושלים, כי לא לרוב עשו ככתוב;",
  "30_6": "וילכו הרצים באיגרות מיד המלך ושריו בכל ישראל ויהודה וכמצוות המלך לאמור: 'בני ישראל, שובו אל ה' אלוהי אברהם יצחק וישראל, וישוב אל הפליטה הנשארת לכם מכף מלכי אשור!;",
  "30_7": "ואל תהיו כאבותיכם וכאחיכם אשר מעלו בה' אלוהי אבותיהם וייתנם לשמה כאשר אתם רואים!;",
  "30_8": "עתה אל תקשו עורפכם כאבותיכם, תנו יד לה' ובואו למקדשו אשר הקדיש לעולם ועבדו את ה' אלוהיכם, וישוב מכם חרון אפו!;",
  "30_9": "כי בשובכם על ה' אחיכם ובניכם לרחמים לפני שוביהם ולשוב לארץ הזאת, כי חנון ורחום ה' אלוהיכם ולא יסיר פנים מכם אם תשובו אליו!';",
  "30_10": "ויהיו הרצים עוברים מעיר לעיר בארץ אפרים ומנשה ועד זבולון; ויהיו משחיקים עליהם ומלעיגים בם;",
  "30_11": "אך אנשים מאשר וממנשה ומזבולון נכנעו ויבואו לירושלים;",
  "30_12": "גם ביהודה הייתה יד האלוהים לתת להם לב אחד לעשות מצוות המלך והשרים בדבר ה';",
  "30_13": "וייאספו ירושלים עם רב לעשות את חג המצות בחודש השני, קהל לרב מאוד;",
  "30_14": "ויקומו ויסירו את המזבחות אשר בירושלים, ואת כל המקטרות הסירו וישליכו לנחל קדרון;",
  "30_15": "וישחטו הפסח בארבעה עשר לחודש השני; והכוהנים והלוויים נכלמו ויתקדשו, ויביאו עולות בית ה';",
  "30_16": "ויעמדו על עומדם כמשפטם כתורת משה איש האלוהים; הכוהנים זורקים את הדם מיד הלוויים;",
  "30_17": "כי רבת בקהל אשר לא התקדשו; והלוויים על שחיטת הפסחים לכל לא טהור להקדיש לה';",
  "30_18": "כי מרבית העם, רבת מאפרים ומנשה יששכר וזבולון, לא הטהרו כי אכלו את הפסח בלא ככתוב; כי התפלל יחזקיהו עליהם לאמור: 'ה' הטוב יכפר בעד –",
  "30_19": "כל לבבו הכין לדרוש האלוהים ה' אלוהי אבותיו, ולא כטהרת הקודש!';",
  "30_20": "וישמע ה' אל יחזקיהו, וירפא את העם;",
  "30_21": "ויעשו בני ישראל הנמצאים בירושלים את חג המצות שבעת ימים בשמחה גדולה; ומהללים לה' יום ביום הלוויים והכוהנים בכלי עוז לה';",
  "30_22": "וידבר יחזקיהו על לב כל הלוויים המשכילים שכל טוב לה'; ויאכלו את המועד שבעת הימים מזבחים זבחי שלמים ומתודים לה' אלוהי אבותיהם;",
  "30_23": "וייוועצו כל הקהל לעשות שבעת ימים אחרים; ויעשו שבעת ימים בשמחה;",
  "30_24": "כי יחזקיהו מלך יהודה הרים לקהל אלף פרים ושבעת אלפים צאן, והשרים הרימו לקהל פרים אלף וצאן עשרת אלפים; ויתקדשו כוהנים לרוב;",
  "30_25": "וישמחו כל קהל יהודה והכוהנים והלוויים, וכל הקהל הבאים מישראל, והגרים הבאים מארץ ישראל והיושבים ביהודה;",
  "30_26": "ותהי שמחה גדולה בירושלים, כי מימי שלמה בן דוד מלך ישראל לא הייתה כזאת בירושלים;",
  "30_27": "ויקומו הכוהנים הלוויים ויברכו את העם; ויישמע בקולם, ותבוא תפילתם למעון קודשו לשמים.",
  "31_1": "וככלות כל זאת יצאו כל ישראל הנמצאים לערי יהודה וישברו המצבות ויגדעו האשרים וינתצו הבמות והמזבחות מכל יהודה ובנימין ובאפרים ומנשה עד לכלה; וישובו כל בני ישראל איש לאחוזתו לעריהם;",
  "31_2": "ויעמד יחזקיהו את מחלקות הכוהנים והלוויים על מחלקותם איש כפי עבודתו לכוהנים וללוויים לעולה ולשלמים, לשרת ולהודות ולהלל בשערי מחנות ה';",
  "31_3": "ומנת המלך מן רכושו לעולות: לעולות הבוקר והערב, והעולות לשבתות ולחדשים ולמועדים ככתוב בתורת ה';",
  "31_4": "ויאמר לעם יושבי ירושלים לתת מנת הכוהנים והלוויים, למען יחזקו בתורת ה';",
  "31_5": "וכפרוץ הדבר הרבו בני ישראל ראשית דגן, תירוש ויצהר ודבש וכל תבואת שדה; ומעשר הכול לרוב הביאו;",
  "31_6": "ובני ישראל ויהודה היושבים בערי יהודה, גם הם מעשר בקר וצאן ומעשר קודשים המקודשים לה' אלוהיהם הביאו, וייתנו ערימות ערימות;",
  "31_7": "בחודש השלישי החלו הערימות ליסוד, ובחודש השביעי כילו;",
  "31_8": "ויבואו יחזקיהו והשרים ויראו את הערימות, ויברכו את ה' ואת עמו ישראל;",
  "31_9": "וידרוש יחזקיהו על הכוהנים והלוויים על הערימות;",
  "31_10": "ויאמר אליו עזריהו כוהן הראש לבית צדוק ויאמר: 'מהחל התרומה להביא בית ה' אכול ושבוע והותר עד לרוב, כי ה' בירך את עמו והנותר את ההמון הזה!';",
  "31_11": "ויאמר יחזקיהו להכין לשכות בבית ה'; ויכינו;",
  "31_12": "ויביאו את התרומה והמעשר והקודשים באמונה; ועליהם נגיד כונניהו הלוי ושמעי אחיו משנה;",
  "31_13": "ויחיאל ועזזיהו ונחת ועשהאל וירימות ויוזבד ואליאל ויסמכיהו ומחת ובניהו פקידים מיד כונניהו ושמעי אחיו, בפקודת יחזקיהו המלך ועזריהו נגיד בית האלוהים;",
  "31_14": "וקורא בן ימנה הלוי השוער למזרחה על נדבות האלוהים, לתת תרומת ה' וקודשי הקודשים;",
  "31_15": "ועל ידו עדן ומינימין וישוע ושמעיהו אמריהו ושכניהו בערי הכוהנים באמונה, לתת לאחיהם במחלקות כגדול כקטן;",
  "31_16": "מלבד התייחסם לזכרים מבן שלוש שנים ומעלה לכל הבא לבית ה' לדבר יום ביומו לעבודתם במשמרותם כמחלקותיהם;",
  "31_17": "ואת התייחס הכוהנים לבית אבותם, והלוויים מבן עשרים שנה ומעלה במשמרותיהם במחלקותיהם;",
  "31_18": "ולהתייחס בכל טפם נשיהם ובניהם ובנותיהם לכל קהל, כי באמונתם יתקדשו קודש;",
  "31_19": "ולבני אהרון הכוהנים בשדי מגרש עריהם בכל עיר ועיר אנשים אשר ניקבו בשמות לתת מנות לכל זכר בכוהנים ולכל התייחס בלוויים;",
  "31_20": "ויעש כזאת יחזקיהו בכל יהודה; ויעש הטוב והישר והאמת לפני ה' אלוהיו;",
  "31_21": "ובכל מלאכה אשר החל בעבודת בית האלוהים ובתורה ובמצווה לדרוש לאלוהיו – בכל לבבו עשה והצליח.",
  "32_1": "אחרי הדברים והאמת האלה, בא סנחריב מלך אשור ויבוא ביהודה, ויחן על הערים הבצורות ויאמר לבקעם אליו;",
  "32_2": "וירא יחזקיהו כי בא סנחריב ופניו למלחמה על ירושלים;",
  "32_3": "וייוועץ עם שריו וגיבוריו לסתום את מימי העיינות אשר מחוץ לעיר; ויעזרוהו;",
  "32_4": "וייקבצו עם רב ויסתמו את כל המעיינות ואת הנחל השוטף בתוך הארץ לאמור: 'למה יבואו מלכי אשור ומצאו מים רבים?!';",
  "32_5": "ויתחזק ויבן את כל החומה הפרוצה ויעל על המגדלים ולחוצה החומה האחרת ויחזק את המלוא עיר דוד, ויעש שלח לרוב ומגנים;",
  "32_6": "וייתן שרי מלחמות על העם, ויקבצם אליו אל רחוב שער העיר וידבר על לבבם לאמור:",
  "32_7": "'חזקו ואמצו, אל תיראו ואל תחתו מפני מלך אשור ומלפני כל ההמון אשר עימו, כי עימנו רב מאשר עימו!;",
  "32_8": "עימו זרוע בשר, ועימנו ה' אלוהינו לעוזרנו ולהילחם מלחמותינו!'; וייסמכו העם על דברי יחזקיהו מלך יהודה;",
  "32_9": "אחר זה שלח סנחריב מלך אשור עבדיו ירושלימה – והוא על לכיש וכל ממשלתו עימו – על יחזקיהו מלך יהודה ועל כל יהודה אשר בירושלים לאמור:",
  "32_10": "'כה אמר סנחריב מלך אשור: על מה אתם בוטחים ויושבים במצור בירושלים?!;",
  "32_11": "הלא יחזקיהו מסית אתכם לתת אתכם למות ברעב ובצמא לאמור: \"ה' אלוהינו יצילנו מכף מלך אשור\"?!;",
  "32_12": "הלא הוא יחזקיהו הסיר את במותיו ואת מזבחותיו, ויאמר ליהודה ולירושלים לאמור: \"לפני מזבח אחד תשתחוו ועליו תקטירו\"?!;",
  "32_13": "הלא תדעו מה עשיתי אני ואבותיי לכל עמי הארצות?! היכול יכלו אלוהי גויי הארצות להציל את ארצם מידי?!;",
  "32_14": "מי בכל אלוהי הגויים האלה אשר החרימו אבותיי אשר יכול להציל את עמו מידי, כי יוכל אלוהיכם להציל אתכם מידי?!;",
  "32_15": "ועתה אל ישיא אתכם יחזקיהו ואל יסית אתכם כזאת ואל תאמינו לו, כי לא יוכל כל אלוה כל גוי וממלכה להציל עמו מידי ומיד אבותיי, אף כי אלוהיכם לא יציל אתכם מידי!';",
  "32_16": "ועוד דיברו עבדיו על ה' האלוהים ועל יחזקיהו עבדו;",
  "32_17": "וספרים כתב לחרף לה' אלוהי ישראל ולאמור עליו: 'כאלוהי גויי הארצות אשר לא הצילו עמם מידי, כן לא יציל אלוהי יחזקיהו עמו מידי!';",
  "32_18": "ויקראו בקול גדול יהודית על עם ירושלים אשר על החומה ליראם ולבהלם, למען ילכדו את העיר;",
  "32_19": "וידברו אל אלוהי ירושלים כאלוהי עמי הארץ מעשה ידי האדם;",
  "32_20": "ויתפלל יחזקיהו המלך וישעיהו בן אמוץ הנביא על זאת, ויזעקו השמימה;",
  "32_21": "וישלח ה' מלאך ויכחד כל גיבור חיל ונגיד ושר במחנה מלך אשור; וישב בבושת פנים לארצו, ויבוא בית אלוהיו ומיציאי מעיו שם הפילוהו בחרב;",
  "32_22": "ויושע ה' את יחזקיהו ואת יושבי ירושלים מיד סנחריב מלך אשור ומיד הכול, וינהלם מסביב;",
  "32_23": "ורבים מביאים מנחה לה' לירושלים ומגדנות ליחזקיהו מלך יהודה, ויינשא לעיני כל הגויים מאחרי כן;",
  "32_24": "בימים ההם חלה יחזקיהו עד למות, ויתפלל אל ה' ויאמר לו ומופת נתן לו;",
  "32_25": "ולא כגמול עליו השיב יחזקיהו כי גבה לבו, ויהי עליו קצף ועל יהודה וירושלים;",
  "32_26": "וייכנע יחזקיהו בגובה לבו, הוא ויושבי ירושלים, ולא בא עליהם קצף ה' בימי יחזקיהו;",
  "32_27": "ויהי ליחזקיהו עושר וכבוד עד למאוד, ואוצרות עשה לו לכסף ולזהב ולאבן יקרה ולבשמים ולמגנים ולכל כלי חמדה;",
  "32_28": "ומסכנות לתבואת דגן ותירוש ויצהר, וארוות לכל בהמה ובהמה ועדרים לארוות;",
  "32_29": "וערים עשה לו ומקנה צאן ובקר לרוב, כי נתן לו אלוהים רכוש רב מאוד;",
  "32_30": "והוא יחזקיהו סתם את מוצא מימי גיחון העליון ויישרם למטה מערבה לעיר דוד, ויצלח יחזקיהו בכל מעשהו;",
  "32_31": "וכן במליצי שרי בבל המשלחים עליו לדרוש המופת אשר היה בארץ עזבו האלוהים לנסותו, לדעת כל בלבבו;",
  "32_32": "ויתר דברי יחזקיהו וחסדיו, הינם כתובים בחזון ישעיהו בן אמוץ הנביא על ספר מלכי יהודה וישראל;",
  "32_33": "וישכב יחזקיהו עם אבותיו ויקברוהו במעלה קברי בני דוד, וכבוד עשו לו במותו כל יהודה ויושבי ירושלים; וימלוך מנשה בנו תחתיו.",
  "33_1": "בן שתים עשרה שנה מנשה במלכו, וחמישים וחמש שנה מלך בירושלים;",
  "33_2": "ויעש הרע בעיני ה' כתועבות הגויים אשר הוריש ה' מפני בני ישראל;",
  "33_3": "וישב ויבן את הבמות אשר ניתץ יחזקיהו אביו, ויקם מזבחות לבעלים ויעש אשרות, וישתחו לכל צבא השמים ויעבוד אותם;",
  "33_4": "ובנה מזבחות בבית ה' אשר אמר ה': 'בירושלים יהיה שמי לעולם!';",
  "33_5": "ויבן מזבחות לכל צבא השמים בשתי חצרות בית ה';",
  "33_6": "והוא העביר את בניו באש בגיא בן הינום ועונן וניחש וכישף ועשה אוב וידעוני; הרבה לעשות הרע בעיני ה' להכעיסו;",
  "33_7": "וישם את פסל הסמל אשר עשה בבית האלוהים אשר אמר אלוהים אל דוד ואל שלמה בנו: 'בבית הזה ובירושלים אשר בחרתי מכל שבטי ישראל אשים את שמי לעולם!;",
  "33_8": "ולא אוסיף להסיר את רגל ישראל מן האדמה אשר העמדתי לאבותיכם, רק אם ישמרו לעשות את כל אשר ציוויתים לכל התורה והחוקים והמשפטים ביד משה!';",
  "33_9": "ויתע מנשה את יהודה ויושבי ירושלים לעשות רע מן הגויים אשר השמיד ה' מפני בני ישראל;",
  "33_10": "וידבר ה' אל מנשה ואל עמו, ולא הקשיבו;",
  "33_11": "ויבא ה' עליהם את שרי הצבא אשר למלך אשור, וילכדו את מנשה בחוחים (בכבלי ברזל) ויאסרוהו בנחושתיים ויוליכוהו בבלה;",
  "33_12": "וכהצר לו, חילה והתחנן את פני ה' אלוהיו, וייכנע מאוד מלפני אלוהי אבותיו;",
  "33_13": "ויתפלל אליו, וייעתר לו וישמע תחינתו וישיבהו ירושלים למלכותו; ויידע מנשה כי ה' הוא האלוהים;",
  "33_14": "ואחרי כן בנה חומה חיצונה לעיר דוד מערבה לגיחון בנחל ולבוא שער הדגים וסבב לעופל ויגביהה מאוד; וישם שרי חיל בכל הערים הבצורות ביהודה;",
  "33_15": "ויסר את אלוהי הנכר ואת הסמל מבית ה' ואת כל המזבחות אשר בנה בהר בית ה' ובירושלים, וישלך חוצה לעיר;",
  "33_16": "ויכן את מזבח ה' ויזבח עליו זבחי שלמים ותודה, ויאמר ליהודה לעבוד את ה' אלוהי ישראל;",
  "33_17": "אבל עוד העם זובחים בבמות, רק לה' אלוהיהם;",
  "33_18": "ויתר דברי מנשה ותפילתו אל אלוהיו ודברי החוזים המדברים אליו בשם ה' אלוהי ישראל, הינם על דברי מלכי ישראל;",
  "33_19": "ותפילתו והיעתר לו וכל חטאתו ומעלו והמקומות אשר בנה בהם במות והעמיד האשרים והפסילים לפני היכנעו, הנם כתובים על דברי חוזי;",
  "33_20": "וישכב מנשה עם אבותיו ויקברוהו ביתו; וימלוך אמון בנו תחתיו;",
  "33_21": "בן עשרים ושתיים שנה אמון במלכו, ושתיים שנים מלך בירושלים;",
  "33_22": "ויעש הרע בעיני ה' כאשר עשה מנשה אביו; ולכל הפסילים אשר עשה מנשה אביו זבח אמון ויעבדם;",
  "33_23": "ולא נכנע מלפני ה' כהיכנע מנשה אביו, כי הוא אמון הרבה אשמה;",
  "33_24": "וייקשרו עליו עבדיו, וימיתוהו בביתו;",
  "33_25": "ויכו עם הארץ את כל הקושרים על המלך אמון; וימליכו עם הארץ את יאשיהו בנו תחתיו.",
  "34_1": "בן שמונה שנים יאשיהו במלכו, ושלושים ואחת שנה מלך בירושלים;",
  "34_2": "ויעש הישר בעיני ה', וילך בדרכי דוד אביו ולא סר ימין ושמאל;",
  "34_3": "ובשמונה שנים למלכו והוא עודנו נער (בן 16), החל לדרוש לאלוהי דוד אביו; ובשתים עשרה שנה החל לטהר את יהודה וירושלים מן הבמות והאשרים והפסילים והמסכות;",
  "34_4": "וינתצו לפניו את מזבחות הבעלים, והחמנים (מזבחות השמש) אשר למעלה מעליהם גידע; והאשרים והפסילים והמסכות שיבר והדק, ויזרוק על פני קברי הזובחים להם;",
  "34_5": "ועצמות כוהנים שרף על מזבחותיהם, ויטהר את יהודה ואת ירושלים;",
  "34_6": "ובערי מנשה ואפרים ושמעון ועד נפתלי בחרבותיהם סביב;",
  "34_7": "ויינתץ את המזבחות ואת האשרים והפסילים כיתת להדק, וכל החמנים גידע בכל ארץ ישראל; וישב לירושלים;",
  "34_8": "ובשנת שמונה עשרה למלכו לטהר הארץ והבית, שלח את שפן בן אצליהו ואת מעשיהו שר העיר ואת יואח בן יואחז המזכיר לחזק את בית ה' אלוהיו;",
  "34_9": "ויבואו אל חלקיהו הכוהן הגדול וייתנו את הכסף המובא בית האלוהים אשר אספו הלוויים שומרי הסף מיד מנשה ואפרים ומכל שארית ישראל ומכל יהודה ובנימין ויושבי ירושלים;",
  "34_10": "וייתנו על יד עושי המלאכה המופקדים בבית ה', וייתנו אותו עושי המלאכה אשר עושים בבית ה' לבדוק ולחזק הבית;",
  "34_11": "וייתנו לחרשים ולבונים לקנות אבני מחצב ועצים למחברות ולקרות את הבתים אשר השחיתו מלכי יהודה;",
  "34_12": "והאנשים עושים באמונה במלאכה; ועליהם מופקדים יחת ועובדיהו הלוויים מן בני מררי, וזכריה ומשולם מן בני הקהתים לנצח, והלוויים כל מבין בכלי שיר;",
  "34_13": "ועל הסבלים ומנצחים לכל עושה מלאכה לעבודה ועבודה; ומן הלוויים סופרים ושוטרים ושוערים;",
  "34_14": "ובהוציאם את הכסף המובא בית ה', מצא חלקיהו הכוהן את ספר תורת ה' ביד משה;",
  "34_15": "ויען חלקיהו ויאמר אל שפן הסופר: 'ספר התורה מצאתי בבית ה'!'; וייתן חלקיהו את הספר אל שפן;",
  "34_16": "ויבא שפן את הספר אל המלך, וישב עוד את המלך דבר לאמור: 'כל אשר ניתן ביד עבדיך המה עושים;",
  "34_17": "ויתיכו את הכסף הנמצא בבית ה', וייתנוהו על יד המופקדים ועל יד עושי המלאכה';",
  "34_18": "ויגד שפן הסופר למלך לאמור: 'ספר נתן לי חלקיהו הכוהן!'; ויקרא בו שפן לפני המלך;",
  "34_19": "ויהי כשמוע המלך את דברי התורה, ויקרע את בגדיו בחרדה גדולה;",
  "34_20": "ויצו המלך את חלקיהו ואת אחיקם בן שפן ואת עבדון בן מיכה ואת שפן הסופר ואת עשיה עבד המלך לאמור:",
  "34_21": "'לכו דרשו את ה' בעדי ובעד הנשאר בישראל וביהודה על דברי הספר אשר נמצא! כי גדולה חמת ה' אשר ניתכה בנו על אשר לא שמרו אבותינו את דבר ה' לעשות ככל הכתוב על הספר הזה!';",
  "34_22": "וילך חלקיהו ואשר אמר המלך אל חולדה הנביאה אשת שלום בן תוקהת בן חסרה שומר הבגדים, והיא יושבת בירושלים במשנה; וידברו אליה כזאת;",
  "34_23": "ותאמר להם: 'כה אמר ה' אלוהי ישראל: אמרו לאיש אשר שלח אתכם אליי:",
  "34_24": "כה אמר ה': הנני מביא רעה על המקום הזה ועל יושביו – את כל האלות הכתובות על הספר אשר קראו לפני מלך יהודה!;",
  "34_25": "תחת אשר עזבוני ויקטרו לאלוהים אחרים למען הכעיסני בכל מעשי ידיהם, ותיתך חמתי במקום הזה ולא תכבה!;",
  "34_26": "ואל מלך יהודה השולח אתכם לדרוש בה', כה תאמרו אליו: כה אמר ה' אלוהי ישראל: הדברים אשר שמעת –",
  "34_27": "יען רך לבבך ותיכנע מלפני אלוהים בשומעך את דבריו על המקום הזה ועל יושביו, ותיכנע לפניי ותקרע את בגדיך ותבך לפניי – וגם אני שמעתי, נאום ה'!",
  "34_28": "הנני אוסיפך אל אבותיך ונאספת אל קברותיך בשלום, ולא תראינה עיניך בכל הרעה אשר אני מביא על המקום הזה ועל יושביו!'; וישיבו את המלך דבר;",
  "34_29": "וישלח המלך, וייאסוף את כל זקני יהודה וירושלים;",
  "34_30": "ויעל המלך בית ה' וכל איש יהודה ויושבי ירושלים והכוהנים והלוויים וכל העם למגדול ועד קטן, ויקרא באוזניהם את כל דברי ספר הברית הנמצא בבית ה';",
  "34_31": "ויעמוד המלך על עומדו ויכרות את הברית לפני ה' ללכת אחרי ה' ולשמור מצוותיו ועדותיו וחוקותיו בכל לבבו ובכל נפשו, לעשות את דברי הברית הכתובים על הספר הזה;",
  "34_32": "ויעמד את כל הנמצא בירושלים ובנימין; ויעשו יושבי ירושלים כברית אלוהים אלוהי אבותיהם;",
  "34_33": "ויסר יאשיהו את כל התועבות מכל הארצות אשר לבני ישראל, ויעבד את כל הנמצא בישראל לעבוד את ה' אלוהיהם; כל ימיו לא סרו מאחרי ה' אלוהי אבותיהם.",
  "35_1": "ויעש יאשיהו בירושלים פסח לה', וישחטו הפסח בארבעה עשר לחודש הראשון;",
  "35_2": "ויעמד הכוהנים על משמרותם, ויחזקם לעבודת בית ה';",
  "35_3": "ויאמר ללוויים המבינים לכל ישראל הקדושים לה': 'תנו את ארון הקודש בבית אשר בנה שלמה בן דוד מלך ישראל, אין לכם משא בכתף; עתה עבדו את ה' אלוהיכם ואת עמו ישראל;",
  "35_4": "והיכונו לבית אבותיכם כמחלקותיכם בכתב דוד מלך ישראל ובמכתב שלמה בנו;",
  "35_5": "ועמדו בקודש לפלגות בית האבות לאחיכם בני העם, וחלקת בית אב ללוויים;",
  "35_6": "ושחטו הפסח והתקדשו, והכינו לאחיכם לעשות כדבר ה' ביד משה!';",
  "35_7": "וירם יאשיהו לבני העם צאן כבשים ובני עיזים הכול לפסחים לכל הנמצא למספר שלושים אלף, ובקר שלושת אלפים; אלה מרכוש המלך;",
  "35_8": "ושריו לנדבה לעם לכוהנים וללוויים הרימו; חלקיה וזכריהו ויחיאל נגידי בית האלוהים לכוהנים נתנו לפסחים אלפיים ושש מאות, ובקר שלוש מאות;",
  "35_9": "וכונניהו ושמעיהו ונתנאל אחיו וחשביהו ויעיאל ויוזבד שרי הלוויים הרימו ללוויים לפסחים חמשת אלפים, ובקר חמש מאות;",
  "35_10": "ותיכון העבודה; ויעמדו הכוהנים על עומדם והלוויים על מחלקותם כמצוות המלך;",
  "35_11": "וישחטו הפסח; ויזרקו הכוהנים את הדם מידם, והלוויים מפשיטים;",
  "35_12": "ויסירו העולה לתתם לפלגות בית אבות לבני העם להקריב לה' ככתוב בספר משה, וכן לבקר;",
  "35_13": "ויבשלו הפסח באש כמשפט; והקודשים בישלו בסירות ובדוודים ובצלחות, ויריצו לכל בני העם;",
  "35_14": "ואחר הכינו להם ולכוהנים, כי הכוהנים בני אהרון בהעלות העולה והחלבים עד לילה; והלוויים הכינו להם ולכוהנים בני אהרון;",
  "35_15": "והממשוררים בני אסף על מעמדם כמצוות דוד ואסף והימן וידותון חוזה המלך, והשוערים לשער ושער; אין להם לסור מעל עבודתם, כי אחיהם הלוויים הכינו להם;",
  "35_16": "ותיכון כל עבודת ה' ביום ההוא לעשות הפסח והעלות עולות על מזבח ה', כמצוות המלך יאשיהו;",
  "35_17": "ויעשו בני ישראל הנמצאים את הפסח בעת ההיא, ואת חג המצות שבעת ימים;",
  "35_18": "ולא נעשה פסח כמוהו בישראל מימי שמואל הנביא; וכל מלכי ישראל לא עשו כפסח אשר עשה יאשיהו והכוהנים והלוויים וכל יהודה וישראל הנמצא ויושבי ירושלים;",
  "35_19": "בשמונה עשרה שנה למלכות יאשיהו נעשה הפסח הזה;",
  "35_20": "אחרי כל זאת אשר הכין יאשיהו את הבית, עלה נכו מלך מצרים להילחם בכרכמיש על פרת; וייצא לקראתו יאשיהו;",
  "35_21": "וישלח אליו מלאכים לאמור: 'מה לי ולך מלך יהודה?! לא עליך אתה היום, כי אל בית מלחמתי, ואלוהים אמר לבהלני! חדל לך מאלוהים אשר עימי ואל ישחיתך!';",
  "35_22": "ולא הסב יאשיהו פניו ממנו כי להילחם בו התחפש, ולא שמע אל דברי נכו מפי אלוהים; ויבוא להילחם בבקעת מגידו;",
  "35_23": "ויורו היורים למלך יאשיהו; ויאמר המלך לעבדיו: 'העבירוני, כי החלייתי מאוד!';",
  "35_24": "ויעבירוהו עבדיו מן המרכבה וירכיבוהו על רכב המשנה אשר לו ויוליכוהו ירושלים, וימת וייקבר בקברות אבותיו; וכל יהודה וירושלים מתאבלים על יאשיהו;",
  "35_25": "ויקונן ירמיהו על יאשיהו, ויאמרו כל השרים והשרות בקינותיהם על יאשיהו עד היום וייתנום לחוק על ישראל; והנם כתובים על הקינות;",
  "35_26": "ויתר דברי יאשיהו וחסדיו ככתוב בתורת ה';",
  "35_27": "ודבריו הראשונים והאחרונים, הנם כתובים על ספר מלכי ישראל ויהודה.",
  "36_1": "וייקחו עם הארץ את יהואחז בן יאשיהו, וימליכו אותו תחת אביו בירושלים;",
  "36_2": "בן שלוש ועשרים שנה יואחז במלכו, ושלושה חודשים מלך בירושלים;",
  "36_3": "ויסירהו מלך מצרים בירושלים, ויענוש את הארץ מאה כיכר כסף וכיכר זהב;",
  "36_4": "וימלך מלך מצרים את אליקים אחיו על יהודה וירושלים ויסב את שמו יהויקים; ואת יואחז אחיו לקח נכו ויביאהו מצרימה;",
  "36_5": "בן עשרים וחמש שנה יהויקים במלכו, ואחת עשרה שנה מלך בירושלים; ויעש הרע בעיני ה' אלוהיו;",
  "36_6": "עליו עלה נבוכדנאצר מלך בבל, ויאסרהו בנחושתיים להוליכו בבלה;",
  "36_7": "ומכלי בית ה' הביא נבוכדנאצר לבבל, וייתנם בהיכלו בבבל;",
  "36_8": "ויתר דברי יהויקים ותועבותיו אשר עשה והנמצא עליו, הנם כתובים על ספר מלכי ישראל ויהודה; וימלוך יהויכין בנו תחתיו;",
  "36_9": "בן שמונה (עשרה) שנים יהויכין במלכו, ושלושה חודשים ועשרה ימים מלך בירושלים; ויעש הרע בעיני ה';",
  "36_10": "ולתשובת השנה שלח המלך נבוכדנאצר ויביאהו בבלה עם כלי חמדת בית ה', וימלך את צדקיהו אחיו (דודו) על יהודה וירושלים;",
  "36_11": "בן עשרים ואחת שנה צדקיהו במלכו, ואחת עשרה שנה מלך בירושלים;",
  "36_12": "ויעש הרע בעיני ה' אלוהיו; לא נכנע מלפני ירמיהו הנביא מפי ה';",
  "36_13": "וגם במלך נבוכדנאצר מרד אשר השביעו באלוהים, ויקש את עורפו ויאמץ את לבבו משוב אל ה' אלוהי ישראל;",
  "36_14": "גם כל שרי הכוהנים והעם הרבו למעול מעל ככל תועבות הגויים, ויטמאו את בית ה' אשר הקדיש בירושלים;",
  "36_15": "וישלח ה' אלוהי אבותיהם עליהם ביד מלאכיו השכם ושלוח, כי חמל על עמו ועל מעונו;",
  "36_16": "ויהיו מלעיבים במלאכי האלוהים ובוזים דבריו ומתעתעים בנביאיו, עד עלות חמת ה' בעמו עד לאין מרפא;",
  "36_17": "ויעל עליהם את מלך כשדיים, ויהרוג בחוריהם בחרב בבית מקדשם, ולא חמל על בחור ובתולה זקן וישיש; הכול נתן בידו;",
  "36_18": "וכל כלי בית האלוהים הגדולים והקטנים ואוצרות בית ה' ואוצרות המלך ושריו – הכול בבל הביא;",
  "36_19": "וישרפו את בית האלוהים, וינתצו את חומת ירושלים, וכל ארמנותיה שרפו באש, וכל כלי מחמדיה להשחית;",
  "36_20": "ויגל את השארית מן החרב אל בבל, ויהיו לו ולבניו לעבדים עד מלוך ממלכת פרס;",
  "36_21": "למלאות דבר ה' בפי ירמיהו עד רצתה הארץ את שבתותיה; כל ימי הָשַׁמָּה שָׁבָתָה למלאות שבעים שנה;",
  "36_22": "ובשנת אחת לכורש מלך פרס לכלות דבר ה' בפי ירמיהו, העיר ה' את רוח כורש מלך פרס, ויעבר קול בכל מלכותו וגם במכתב לאמור:",
  "36_23": "'כה אמר כורש מלך פרס: כל ממלכות הארץ נתן לי ה' אלוהי השמים, והוא פקד עליי לבנות לו בית בירושלים אשר ביהודה; מי בכם מכל עמו – ה' אלוהיו עימו ויעל!'."
};
